            headers.insert(REFERER, HeaderValue::from_static(BASE_URL));
        }

        match plan.encryption {
            Crypto::Weapi => {
                let mut cookies = self
                    .jar
                    .cookies(&self.config.base_url)
                    .map(|header| {
                        header
                            .to_str()
                            .map(str::to_owned)
                            .map_err(|error| Error::Protocol(error.to_string()))
                    })
                    .transpose()?
                    .unwrap_or_default();
