//! The pure heart of lekima.
//!
//! This crate has no I/O, no runtime and no knowledge of HTTP, audio devices or
//! terminals. It defines the vocabulary shared by every adapter:
//!
//! - [`model`] — catalogue entities (tracks, playlists, users, …)
//! - [`playback`] — the queue and the observable playback state
//! - [`ports`] — the traits adapters must implement
//!
//! Keeping this layer dependency-free is what allows the core rules (queue
//! semantics, repeat/shuffle behaviour, state transitions) to be tested in
//! microseconds and reused by the CLI, the TUI and any future frontend.

pub mod error;
pub mod model;
pub mod playback;
pub mod ports;

pub use error::{DomainError, Result};
pub use model::{
    Album, AlbumId, Artist, ArtistId, Playlist, PlaylistId, Quality, SearchKind, SearchResults,
    Track, TrackId, UserId, UserProfile,
};
pub use playback::{PlaybackState, PlaybackStatus, Queue, RepeatMode};
pub use ports::{AudioEngine, CredentialsStore, MusicService};

//! Domain-level failures.
//!
//! Errors are intentionally coarse: frontends decide how to present them, and
//! adapters map their own error types into these variants.

use thiserror::Error;

#[derive(Debug, Error)]
pub enum DomainError {
    #[error("invalid input: {0}")]
    InvalidInput(String),

    #[error("not found: {0}")]
    NotFound(String),

    #[error("authentication required: {0}")]
    AuthenticationRequired(String),

    #[error("operation not supported by this backend: {0}")]
    Unsupported(String),

    #[error("backend unavailable: {0}")]
    Unavailable(String),

    #[error("playback failed: {0}")]
    Playback(String),
}

pub type Result<T> = std::result::Result<T, DomainError>;

//! Catalogue entities.
//!
//! Identifiers are newtypes rather than raw integers so that a track id can
//! never be passed where a playlist id is expected. All types are serde
//! round-trippable because the same shapes are used for IPC and for the JSON
//! output agents consume.

use serde::{Deserialize, Serialize};

macro_rules! id_type {
    ($($name:ident),+ $(,)?) => {
        $(
            #[derive(
                Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize,
            )]
            #[serde(transparent)]
            pub struct $name(pub u64);

            impl $name {
                pub const fn new(raw: u64) -> Self {
                    Self(raw)
                }

                pub const fn get(self) -> u64 {
                    self.0
                }
            }

            impl std::fmt::Display for $name {
                fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                    write!(f, "{}", self.0)
                }
            }

            impl std::str::FromStr for $name {
                type Err = crate::DomainError;

                fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
                    value
                        .trim()
                        .parse::<u64>()
                        .map(Self)
                        .map_err(|_| crate::DomainError::InvalidInput(format!(
                            "`{value}` is not a valid {}",
                            stringify!($name)
                        )))
                }
            }
        )+
    };
}

id_type!(TrackId, AlbumId, ArtistId, PlaylistId, UserId);

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Artist {
    pub id: ArtistId,
    pub name: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Album {
    pub id: AlbumId,
    pub name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cover_url: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Track {
    pub id: TrackId,
    pub name: String,
    #[serde(default)]
    pub artists: Vec<Artist>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub album: Option<Album>,
    #[serde(default)]
    pub duration_ms: u64,
}

impl Track {
    /// Human readable "Artist A, Artist B" label.
    #[must_use]
    pub fn artist_names(&self) -> String {
        if self.artists.is_empty() {
            "Unknown artist".to_owned()
        } else {
            self.artists
                .iter()
                .map(|artist| artist.name.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        }
    }

    #[must_use]
    pub fn album_name(&self) -> &str {
        self.album.as_ref().map_or("", |album| album.name.as_str())
    }

    /// Duration rendered as `m:ss`, or `--:--` when unknown.
    #[must_use]
    pub fn duration_label(&self) -> String {
        format_duration_ms(self.duration_ms)
    }
}

#[must_use]
pub fn format_duration_ms(duration_ms: u64) -> String {
    if duration_ms == 0 {
        return "--:--".to_owned();
    }
    let total_seconds = duration_ms / 1000;
    let minutes = total_seconds / 60;
    let seconds = total_seconds % 60;
    if minutes >= 60 {
        format!("{}:{:02}:{:02}", minutes / 60, minutes % 60, seconds)
    } else {
        format!("{minutes}:{seconds:02}")
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Playlist {
    pub id: PlaylistId,
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub track_count: u64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cover_url: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub owner: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct UserProfile {
    pub id: UserId,
    pub nickname: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub avatar_url: Option<String>,
}

/// What a search query may target.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum SearchKind {
    Track,
    Album,
    Artist,
    Playlist,
}

impl SearchKind {
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Track => "track",
            Self::Album => "album",
            Self::Artist => "artist",
            Self::Playlist => "playlist",
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct SearchResults {
    #[serde(default)]
    pub tracks: Vec<Track>,
    #[serde(default)]
    pub playlists: Vec<Playlist>,
    #[serde(default)]
    pub artists: Vec<Artist>,
    #[serde(default)]
    pub total: u64,
}

/// Requested streaming bitrate class.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Quality {
    Standard,
    Higher,
    #[default]
    Exhigh,
    Lossless,
}

impl Quality {
    #[must_use]
    pub const fn bitrate(self) -> u32 {
        match self {
            Self::Standard => 128_000,
            Self::Higher => 192_000,
            Self::Exhigh => 320_000,
            Self::Lossless => 999_000,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{Track, format_duration_ms};

    #[test]
    fn duration_formatting_handles_unknown_and_hours() {
        assert_eq!(format_duration_ms(0), "--:--");
        assert_eq!(format_duration_ms(5_000), "0:05");
        assert_eq!(format_duration_ms(245_000), "4:05");
        assert_eq!(format_duration_ms(3_725_000), "1:02:05");
    }

    #[test]
    fn track_artist_label_is_never_empty() {
        let track = Track {
            id: 1.into(),
            name: "mota".to_owned(),
            artists: Vec::new(),
            album: None,
            duration_ms: 0,
        };
        assert_eq!(track.artist_names(), "Unknown artist");
    }
}

//! Queue rules and observable playback state.
//!
//! Queue semantics live here rather than in the daemon so they are testable
//! without a runtime, a socket or an audio device.

use serde::{Deserialize, Serialize};

use crate::model::Track;

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum PlaybackStatus {
    #[default]
    Stopped,
    Playing,
    Paused,
}

impl PlaybackStatus {
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Stopped => "stopped",
            Self::Playing => "playing",
            Self::Paused => "paused",
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum RepeatMode {
    #[default]
    Off,
    All,
    One,
}

impl RepeatMode {
    /// Cycles off -> all -> one -> off, matching the `r` key in the TUI.
    #[must_use]
    pub const fn cycle(self) -> Self {
        match self {
            Self::Off => Self::All,
            Self::All => Self::One,
            Self::One => Self::Off,
        }
    }

    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Off => "off",
            Self::All => "all",
            Self::One => "one",
        }
    }
}

/// Everything a client needs to render a "now playing" view.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PlaybackState {
    pub status: PlaybackStatus,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub track: Option<Track>,
    #[serde(default)]
    pub position_ms: u64,
    #[serde(default = "default_volume")]
    pub volume: f32,
    #[serde(default)]
    pub muted: bool,
    #[serde(default)]
    pub repeat: RepeatMode,
    #[serde(default)]
    pub shuffle: bool,
    #[serde(default)]
    pub queue_length: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub queue_index: Option<usize>,
}

const fn default_volume() -> f32 {
    0.7
}

impl Default for PlaybackState {
    fn default() -> Self {
        Self {
            status: PlaybackStatus::Stopped,
            track: None,
            position_ms: 0,
            volume: default_volume(),
            muted: false,
            repeat: RepeatMode::Off,
            shuffle: false,
            queue_length: 0,
            queue_index: None,
        }
    }
}

impl PlaybackState {
    /// Effective gain: muted playback is silent regardless of the stored level.
    #[must_use]
    pub fn effective_volume(&self) -> f32 {
        if self.muted { 0.0 } else { self.volume.clamp(0.0, 1.0) }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct Queue {
    tracks: Vec<Track>,
    current: Option<usize>,
}

impl Queue {
    #[must_use]
    pub fn new(tracks: Vec<Track>) -> Self {
        let current = if tracks.is_empty() { None } else { Some(0) };
        Self { tracks, current }
    }

    #[must_use]
    pub fn tracks(&self) -> &[Track] {
        &self.tracks
    }

    #[must_use]
    pub fn len(&self) -> usize {
        self.tracks.len()
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.tracks.is_empty()
    }

    #[must_use]
    pub fn current_index(&self) -> Option<usize> {
        self.current
    }

    #[must_use]
    pub fn current(&self) -> Option<&Track> {
        self.current
            .and_then(|index| self.tracks.get(index))
    }

    #[must_use]
    pub fn get(&self, index: usize) -> Option<&Track> {
        self.tracks.get(index)
    }

    /// Appends a track. Returns its index.
    pub fn push(&mut self, track: Track) -> usize {
        self.tracks.push(track);
        if self.current.is_none() {
            self.current = Some(0);
        }
        self.tracks.len() - 1
    }

    pub fn extend(&mut self, tracks: impl IntoIterator<Item = Track>) {
        for track in tracks {
            self.push(track);
        }
    }

    /// Inserts after the currently playing track ("play next").
    pub fn insert_next(&mut self, track: Track) {
        match self.current {
            Some(index) => {
                self.tracks.insert(index + 1, track);
            }
            None => self.push(track),
        }
    }

    /// Replaces the whole queue and selects the first track.
    pub fn replace(&mut self, tracks: Vec<Track>) {
        self.tracks = tracks;
        self.current = if self.tracks.is_empty() { None } else { Some(0) };
    }

    pub fn clear(&mut self) {
        self.tracks.clear();
        self.current = None;
    }

    /// Selects an explicit index.
    pub fn jump(&mut self, index: usize) -> Option<&Track> {
        if index < self.tracks.len() {
            self.current = Some(index);
            self.tracks.get(index)
        } else {
            None
        }
    }

    /// Advances to the next track according to the repeat mode.
    ///
    /// `RepeatMode::One` replays the current track; `All` wraps around;
    /// `Off` stops at the end by returning `None`.
    pub fn advance(&mut self, repeat: RepeatMode) -> Option<&Track> {
        let current = self.current?;
        let next = match repeat {
            RepeatMode::One => Some(current),
            RepeatMode::All => Some((current + 1) % self.tracks.len()),
            RepeatMode::Off => {
                if current + 1 < self.tracks.len() {
                    Some(current + 1)
                } else {
                    None
                }
            }
        };
        self.current = next;
        self.current()
    }

    /// Moves backwards, wrapping only when repeating everything.
    pub fn rewind(&mut self, repeat: RepeatMode) -> Option<&Track> {
        let current = self.current?;
        let previous = if current > 0 {
            Some(current - 1)
        } else if repeat == RepeatMode::All {
            Some(self.tracks.len().saturating_sub(1))
        } else {
            None
        };
        self.current = previous;
        self.current()
    }

    /// Pops the current track, keeping the cursor on the same position.
    pub fn remove_current(&mut self) -> Option<Track> {
        let index = self.current?;
        let removed = self.tracks.remove(index);
        self.current = if self.tracks.is_empty() {
            None
        } else {
            Some(index.min(self.tracks.len() - 1))
        };
        Some(removed)
    }
}

#[cfg(test)]
mod tests {
    use super::{Queue, RepeatMode};
    use crate::model::Track;

    fn track(id: u64) -> Track {
        Track {
            id: id.into(),
            name: format!("track-{id}"),
            artists: Vec::new(),
            album: None,
            duration_ms: 0,
        }
    }

    #[test]
    fn advance_stops_at_the_end_when_repeat_is_off() {
        let mut queue = Queue::new(vec![track(1), track(2)]);
        assert_eq!(queue.current().unwrap().id.get(), 1);
        queue.advance(RepeatMode::Off);
        assert_eq!(queue.current().unwrap().id.get(), 2);
        assert!(queue.advance(RepeatMode::Off).is_none());
    }

    #[test]
    fn advance_wraps_when_repeating_everything() {
        let mut queue = Queue::new(vec![track(1), track(2)]);
        queue.jump(1);
        assert_eq!(queue.advance(RepeatMode::All).unwrap().id.get(), 1);
    }

    #[test]
    fn repeat_one_keeps_the_current_track() {
        let mut queue = Queue::new(vec![track(1), track(2)]);
        assert_eq!(queue.advance(RepeatMode::One).unwrap().id.get(), 1);
    }

    #[test]
    fn insert_next_places_track_after_current() {
        let mut queue = Queue::new(vec![track(1), track(3)]);
        queue.insert_next(track(2));
        assert_eq!(queue.tracks()[1].id.get(), 2);
        assert_eq!(queue.tracks()[2].id.get(), 3);
    }

    #[test]
    fn removing_the_last_track_clears_the_cursor() {
        let mut queue = Queue::new(vec![track(1)]);
        assert!(queue.remove_current().is_some());
        assert!(queue.is_empty());
        assert_eq!(queue.current_index(), None);
    }
}

