//! Ports implemented by infrastructure adapters.
//!
//! The core depends only on these traits. The NetEase adapter, the rodio audio
//! backend and the file-system credential store are swappable, and tests can
//! supply in-memory implementations.

use async_trait::async_trait;

use crate::{
    model::{Quality, SearchKind, SearchResults, Track, TrackId},
    playback::PlaybackState,
    Result,
};

/// Catalogue and account operations backed by a music provider.
#[async_trait]
pub trait MusicService: Send + Sync {
    /// Searches the catalogue.
    async fn search(
        &self,
        query: &str,
        kind: SearchKind,
        limit: u32,
        offset: u32,
    ) -> Result<SearchResults>;

    /// Fetches metadata for a batch of tracks, preserving request order where
    /// the provider allows it.
    async fn tracks(&self, ids: &[TrackId]) -> Result<Vec<Track>>;

    /// Single-track convenience wrapper.
    async fn track(&self, id: TrackId) -> Result<Track> {
        self.tracks(&[id])
            .await?
            .into_iter()
            .next()
            .ok_or_else(|| crate::DomainError::NotFound(format!("track {id}")))
    }

    /// Resolves a playable URL for a track.
    async fn stream_url(&self, id: TrackId, quality: Quality) -> Result<String>;

    /// The signed-in user's playlists, or another user's when supplied.
    async fn playlists(&self, user: Option<crate::model::UserId>) -> Result<Vec<crate::model::Playlist>>;

    /// Tracks of a playlist. Providers that only expose playlist metadata
    /// return [`crate::DomainError::Unsupported`].
    async fn playlist_tracks(&self, id: crate::model::PlaylistId) -> Result<Vec<Track>>;

    /// The account currently authenticated against the provider, if any.
    async fn current_user(&self) -> Result<Option<crate::model::UserProfile>>;

    /// Plain-text lyrics, when the provider exposes them.
    async fn lyrics(&self, id: TrackId) -> Result<String>;
}

/// Decides what to play and how the device reports progress.
#[async_trait]
pub trait AudioEngine: Send + Sync {
    /// Starts playback of a remote stream, replacing whatever was playing.
    async fn play_url(&self, url: &str) -> Result<()>;

    fn pause(&self) -> Result<()>;

    fn resume(&self) -> Result<()>;

    fn stop(&self) -> Result<()>;

    /// Seeks within the current track.
    fn seek(&self, position_ms: u64) -> Result<()>;

    /// Sets linear gain in `0.0..=1.0`.
    fn set_volume(&self, gain: f32) -> Result<()>;

    /// Current position of the playing track.
    fn position_ms(&self) -> u64;

    /// True when the current track has played to completion.
    fn is_finished(&self) -> bool;

    /// True while a track is loaded (playing or paused).
    fn has_track(&self) -> bool;
}

/// Extension point for `status` output in frontends that do not own the daemon.
pub type StateSnapshot = PlaybackState;

/// Persists the provider session (cookies) between runs.
pub trait CredentialsStore: Send + Sync {
    fn load(&self) -> Result<Option<String>>;

    fn save(&self, cookie: &str) -> Result<()>;

    fn clear(&self) -> Result<()>;
}

//! Configuration, XDG paths and the persisted provider session.
//!
//! Precedence is: built-in defaults, then `config.toml`, then environment
//! variables. `LEKIMA_CONFIG_DIR` relocates all state, which keeps tests and
//! CI hermetic.

mod config;
mod paths;
mod session;

pub use config::{Config, DaemonConfig, PlaybackConfig, ProviderConfig, UiConfig};
pub use paths::Paths;
pub use session::FileCredentials;

pub use config::load as load_config;

//! Filesystem locations owned by lekima.

use std::{
    env,
    path::{Path, PathBuf},
};

use directories::ProjectDirs;

use crate::Config;

const ENV_CONFIG_DIR: &str = "LEKIMA_CONFIG_DIR";
const ENV_SOCKET: &str = "LEKIMA_SOCKET";

#[derive(Debug, Clone)]
pub struct Paths {
    root: PathBuf,
}

impl Paths {
    /// Resolves the state root, honouring `LEKIMA_CONFIG_DIR` first.
    ///
    /// # Errors
    ///
    /// Fails when no home directory can be determined.
    pub fn resolve() -> Result<Self, PathError> {
        if let Some(root) = env::var_os(ENV_CONFIG_DIR) {
            return Ok(Self {
                root: PathBuf::from(root),
            });
        }
        let dirs = ProjectDirs::from("dev", "lekima", "lekima").ok_or(PathError::NoHome)?;
        Ok(Self {
            root: dirs.config_dir().to_path_buf(),
        })
    }

    #[must_use]
    pub fn root(&self) -> &Path {
        &self.root
    }

    #[must_use]
    pub fn config_file(&self) -> PathBuf {
        self.root.join("config.toml")
    }

    #[must_use]
    pub fn session_file(&self) -> PathBuf {
        self.root.join("session.cookies")
    }

    #[must_use]
    pub fn cache_dir(&self) -> PathBuf {
        self.root.join("cache")
    }

    #[must_use]
    pub fn log_file(&self) -> PathBuf {
        self.root.join("lekima.log")
    }

    /// Unix socket the daemon listens on.
    ///
    /// `LEKIMA_SOCKET` wins; otherwise the XDG runtime directory is preferred
    /// so the socket disappears on logout.
    #[must_use]
    pub fn socket(&self) -> PathBuf {
        if let Some(path) = env::var_os(ENV_SOCKET) {
            return PathBuf::from(path);
        }
        env::var_os("XDG_RUNTIME_DIR").map_or_else(
            || self.cache_dir().join("lekima.sock"),
            |dir| PathBuf::from(dir).join("lekima.sock"),
        )
    }

    /// Creates the directories lekima writes to.
    ///
    /// # Errors
    ///
    /// Propagates filesystem failures.
    pub fn ensure(&self) -> std::io::Result<()> {
        std::fs::create_dir_all(&self.root)?;
        std::fs::create_dir_all(self.cache_dir())?;
        Ok(())
    }

    /// Loads the configuration for these paths.
    ///
    /// # Errors
    ///
    /// Propagates parse and I/O failures of an existing config file.
    pub fn config(&self) -> Result<Config, PathError> {
        crate::load_config(&self.config_file())
    }
}

#[derive(Debug, thiserror::Error)]
pub enum PathError {
    #[error("could not determine the home directory")]
    NoHome,
    #[error("failed to read {path}: {source}")]
    Read {
        path: PathBuf,
        source: std::io::Error,
    },
    #[error("failed to parse {path}: {source}")]
    Parse {
        path: PathBuf,
        source: toml::de::Error,
    },
}

//! The `config.toml` schema.

use std::path::Path;

use lekima_domain::Quality;
use serde::{Deserialize, Serialize};

use crate::paths::PathError;

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct Config {
    pub provider: ProviderConfig,
    pub playback: PlaybackConfig,
    pub ui: UiConfig,
    pub daemon: DaemonConfig,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct ProviderConfig {
    /// Enables the short-lived HTTP response cache.
    pub cache: bool,
    /// Seconds a cached response stays valid.
    pub cache_ttl_secs: u64,
}

impl Default for ProviderConfig {
    fn default() -> Self {
        Self {
            cache: true,
            cache_ttl_secs: 180,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct PlaybackConfig {
    pub volume: f32,
    pub quality: Quality,
    /// Start playback automatically once a queue is loaded.
    pub autoplay: bool,
}

impl Default for PlaybackConfig {
    fn default() -> Self {
        Self {
            volume: 0.7,
            quality: Quality::Exhigh,
            autoplay: true,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct UiConfig {
    /// `true` keeps the terminal contents when the TUI exits.
    pub alternate_screen: bool,
    pub show_help_on_start: bool,
}

impl Default for UiConfig {
    fn default() -> Self {
        Self {
            alternate_screen: true,
            show_help_on_start: false,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct DaemonConfig {
    /// Spawn a daemon automatically when a client cannot reach one.
    pub autostart: bool,
    pub log_level: String,
}

impl Default for DaemonConfig {
    fn default() -> Self {
        Self {
            autostart: true,
            log_level: "info".to_owned(),
        }
    }
}

/// Loads `path`, falling back to defaults when the file does not exist.
///
/// # Errors
///
/// Returns [`PathError`] when the file exists but cannot be read or parsed.
pub fn load(path: &Path) -> Result<Config, PathError> {
    match std::fs::read_to_string(path) {
        Ok(raw) => toml::from_str(&raw).map_err(|source| PathError::Parse {
            path: path.to_path_buf(),
            source,
        }),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(Config::default()),
        Err(source) => Err(PathError::Read {
            path: path.to_path_buf(),
            source,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::Config;

    #[test]
    fn partial_config_keeps_defaults_for_missing_sections() {
        let config: Config = toml::from_str("[playback]\nvolume = 0.25\n").unwrap();
        assert!((config.playback.volume - 0.25).abs() < f32::EPSILON);
        assert_eq!(config.daemon.log_level, "info");
        assert!(config.provider.cache);
    }

    #[test]
    fn unknown_keys_are_rejected_so_typos_are_visible() {
        let parsed: Result<Config, _> = toml::from_str("[playback]\nvolum = 1.0\n");
        assert!(parsed.is_err());
    }
}

//! Cookie persistence shared by the daemon and CLI login flows.

use std::{
    fs,
    io::Write,
    os::unix::fs::OpenOptionsExt,
    path::{Path, PathBuf},
};

use lekima_domain::{CredentialsStore, DomainError, Result};

/// A single-line cookie header stored with `0600` permissions.
#[derive(Debug, Clone)]
pub struct FileCredentials {
    path: PathBuf,
}

impl FileCredentials {
    #[must_use]
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into() }
    }

    #[must_use]
    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl CredentialsStore for FileCredentials {
    fn load(&self) -> Result<Option<String>> {
        match fs::read_to_string(&self.path) {
            Ok(raw) if raw.trim().is_empty() => Ok(None),
            Ok(raw) => Ok(Some(raw.trim().to_owned())),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(error) => Err(DomainError::Unavailable(format!(
                "failed to read session file {}: {error}",
                self.path.display()
            ))),
        }
    }

    fn save(&self, cookie: &str) -> Result<()> {
        if let Some(parent) = self.path.parent() {
            fs::create_dir_all(parent).map_err(|error| {
                DomainError::Unavailable(format!(
                    "failed to create {}: {error}",
                    parent.display()
                ))
            })?;
        }
        let mut options = fs::OpenOptions::new();
        options.write(true).create(true).truncate(true).mode(0o600);
        let mut file = options.open(&self.path).map_err(|error| {
            DomainError::Unavailable(format!(
                "failed to open {}: {error}",
                self.path.display()
            ))
        })?;
        file.write_all(cookie.trim().as_bytes()).map_err(|error| {
            DomainError::Unavailable(format!(
                "failed to write {}: {error}",
                self.path.display()
            ))
        })
    }

    fn clear(&self) -> Result<()> {
        match fs::remove_file(&self.path) {
            Ok(()) => Ok(()),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(DomainError::Unavailable(format!(
                "failed to remove {}: {error}",
                self.path.display()
            ))),
        }
    }
}

//! The wire protocol: newline-delimited JSON over a Unix socket.
//!
//! Every frame is one JSON object. Requests carry a client-chosen `id` that is
//! echoed back so a future streaming mode can multiplex. The protocol is
//! intentionally line-oriented and stable: shell scripts, the TUI and code
//! agents all speak the same language.

use lekima_domain::{
    Playlist, PlaylistId, PlaybackState, RepeatMode, SearchKind, SearchResults, Track, TrackId,
    UserProfile,
};
use serde::{Deserialize, Serialize};

/// Largest accepted frame. Guards against a wedged peer exhausting memory.
pub const MAX_FRAME_BYTES: usize = 1024 * 1024;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Request {
    pub id: u64,
    pub command: Command,
}

impl Request {
    #[must_use]
    pub const fn new(id: u64, command: Command) -> Self {
        Self { id, command }
    }
}

/// Client-to-daemon commands.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Command {
    Ping,
    Status,
    /// What would `Play` target?
    Play { target: PlayTarget },
    Pause,
    Resume,
    Toggle,
    Stop,
    Next,
    Prev,
    Seek { position_ms: u64 },
    SetVolume { level: f32 },
    ToggleMute,
    CycleRepeat,
    SetShuffle { enabled: bool },
    Queue,
    Enqueue { tracks: Vec<TrackId>, next: bool },
    ClearQueue,
    Search {
        query: String,
        kind: SearchKind,
        limit: u32,
        offset: u32,
    },
    Playlists,
    PlaylistTracks { id: PlaylistId },
    Lyrics { id: Option<TrackId> },
    Whoami,
    /// Persist a browser cookie header (`MUSIC_U=<redacted> and reload the provider.
    Login { cookie: String },
    Logout,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum PlayTarget {
    /// Search the catalogue and queue the results.
    Query { query: String },
    /// Play known track ids.
    Tracks { ids: Vec<TrackId> },
    /// Play every track of a playlist.
    Playlist { id: PlaylistId },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Response {
    pub id: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub result: Option<Reply>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<ApiError>,
}

impl Response {
    #[must_use]
    pub const fn ok(id: u64, result: Reply) -> Self {
        Self {
            id,
            result: Some(result),
            error: None,
        }
    }

    #[must_use]
    pub fn err(id: u64, error: ApiError) -> Self {
        Self {
            id,
            result: None,
            error: Some(error),
        }
    }

    #[must_use]
    pub const fn is_ok(&self) -> bool {
        self.error.is_none()
    }
}

/// Daemon-to-client payloads.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Reply {
    Pong,
    Ack,
    Status { state: PlaybackState },
    Tracks { tracks: Vec<Track> },
    Search { results: SearchResults },
    Playlists { playlists: Vec<Playlist> },
    Lyrics { text: String },
    User { user: Option<UserProfile> },
    Queue { tracks: Vec<Track>, index: Option<usize> },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApiError {
    pub code: ErrorCode,
    pub message: String,
}

impl ApiError {
    #[must_use]
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }
}

/// Stable, machine-readable failure categories.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ErrorCode {
    /// Malformed request or invalid argument.
    BadRequest,
    /// The provider needs a session.
    Unauthorized,
    NotFound,
    Unsupported,
    /// The provider or network failed.
    Backend,
    /// Playback device failure.
    Playback,
    /// The daemon could not be reached or crashed.
    Daemon,
    Internal,
}

impl From<lekima_domain::DomainError> for ApiError {
    fn from(error: lekima_domain::DomainError) -> Self {
        use lekima_domain::DomainError;
        match error {
            DomainError::InvalidInput(message) => Self::new(ErrorCode::BadRequest, message),
            DomainError::NotFound(message) => Self::new(ErrorCode::NotFound, message),
            DomainError::AuthenticationRequired(message) => {
                Self::new(ErrorCode::Unauthorized, message)
            }
            DomainError::Unsupported(message) => Self::new(ErrorCode::Unsupported, message),
            DomainError::Unavailable(message) => Self::new(ErrorCode::Backend, message),
            DomainError::Playback(message) => Self::new(ErrorCode::Playback, message),
        }
    }
}

#[cfg(test)]
mod tests {
    use lekima_domain::{SearchKind, TrackId};

    use super::{Command, PlayTarget, Request, Response, Reply};

    #[test]
    fn commands_round_trip_through_json() {
        let request = Request::new(
            7,
            Command::Play {
                target: PlayTarget::Tracks {
                    ids: vec![TrackId(1), TrackId(2)],
                },
            },
        );
        let encoded = serde_json::to_string(&request).unwrap();
        assert!(encoded.contains("\"type\":\"play\""));
        let decoded: Request = serde_json::from_str(&encoded).unwrap();
        assert_eq!(decoded.id, 7);
    }

    #[test]
    fn search_kind_is_lowercase_on_the_wire() {
        let encoded = serde_json::to_string(&Command::Search {
            query: "mota".into(),
            kind: SearchKind::Track,
            limit: 20,
            offset: 0,
        })
        .unwrap();
        assert!(encoded.contains("\"kind\":\"track\""));
    }

    #[test]
    fn response_without_result_or_error_is_detectable() {
        let response = Response::ok(1, Reply::Ack);
        assert!(response.is_ok());
        assert!(serde_json::to_string(&response).unwrap().contains("ack"));
    }
}

//! Client side of the daemon protocol.

use std::{
    path::{Path, PathBuf},
    time::Duration,
};

use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::UnixStream,
    time::timeout,
};

use crate::protocol::{ApiError, Command, ErrorCode, Reply, Request, Response, MAX_FRAME_BYTES};

/// How long a single request may take, including connection setup.
pub const REQUEST_TIMEOUT: Duration = Duration::from_secs(60);

#[derive(Debug, thiserror::Error)]
pub enum IpcError {
    #[error("daemon is not running at {path}")]
    NotRunning { path: PathBuf },
    #[error("daemon request failed: {0}")]
    Io(#[from] std::io::Error),
    #[error("daemon sent a malformed frame: {0}")]
    Protocol(String),
    #[error("{message}")]
    Remote { code: ErrorCode, message: String },
    #[error("daemon did not answer within {0:?}")]
    Timeout(Duration),
}

impl IpcError {
    /// True when the failure means "no daemon is listening".
    #[must_use]
    pub fn is_not_running(&self) -> bool {
        matches!(self, Self::NotRunning { .. })
    }
}

impl From<ApiError> for IpcError {
    fn from(error: ApiError) -> Self {
        Self::Remote {
            code: error.code,
            message: error.message,
        }
    }
}

/// Sends one command to the daemon at `socket` and waits for the reply.
///
/// # Errors
///
/// Returns [`IpcError::NotRunning`] when nothing is listening, and
/// [`IpcError::Remote`] when the daemon reports a domain failure.
pub async fn call(socket: &Path, command: Command) -> Result<Reply, IpcError> {
    let stream = match UnixStream::connect(socket).await {
        Ok(stream) => stream,
        Err(error)
            if matches!(
                error.kind(),
                std::io::ErrorKind::NotFound | std::io::ErrorKind::ConnectionRefused
            ) =>
        {
            return Err(IpcError::NotRunning {
                path: socket.to_path_buf(),
            });
        }
        Err(error) => return Err(IpcError::Io(error)),
    };
    call_on(stream, command).await
}

/// Sends one command over an already-connected socket.
///
/// # Errors
///
/// Fails on I/O, framing or timeout problems, or when the daemon reports an
/// application error.
pub async fn call_on(stream: UnixStream, command: Command) -> Result<Reply, IpcError> {
    timeout(REQUEST_TIMEOUT, exchange(stream, command))
        .await
        .map_err(|_| IpcError::Timeout(REQUEST_TIMEOUT))?
}

async fn exchange(stream: UnixStream, command: Command) -> Result<Reply, IpcError> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let request = Request::new(1, command);
    let mut payload =
        serde_json::to_string(&request).map_err(|error| IpcError::Protocol(error.to_string()))?;
    payload.push('\n');
    writer.write_all(payload.as_bytes()).await?;
    writer.flush().await?;

    let mut line = String::new();
    let read = reader.read_line(&mut line).await?;
    if read == 0 {
        return Err(IpcError::Protocol("daemon closed the connection".to_owned()));
    }
    if line.len() > MAX_FRAME_BYTES {
        return Err(IpcError::Protocol("response frame too large".to_owned()));
    }
    let response: Response =
        serde_json::from_str(&line).map_err(|error| IpcError::Protocol(error.to_string()))?;
    match (response.result, response.error) {
        (_, Some(error)) => Err(error.into()),
        (Some(reply), None) => Ok(reply),
        (None, None) => Err(IpcError::Protocol("empty response".to_owned())),
    }
}

/// Checks whether a daemon answers a ping within a short deadline.
pub async fn is_running(socket: &Path) -> bool {
    matches!(
        timeout(Duration::from_millis(750), call(socket, Command::Ping)).await,
        Ok(Ok(Reply::Pong))
    )
}

//! Server side of the daemon protocol.
//!
//! The transport is deliberately boring: accept a line, hand the decoded
//! request to the application, write one line back. All policy lives in the
//! daemon, so this module stays free of business rules.

use std::future::Future;

use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader, BufWriter},
    net::UnixStream,
};

use crate::protocol::{ApiError, ErrorCode, Request, Response, MAX_FRAME_BYTES};

/// Serves requests on one accepted connection until the peer disconnects.
///
/// A malformed frame is answered with an error and the connection is closed:
/// a desynchronised stream cannot be trusted.
///
/// # Errors
///
/// Returns an I/O error when the socket itself fails.
pub async fn serve_connection<F, Fut>(stream: UnixStream, handler: F) -> std::io::Result<()>
where
    F: Fn(Request) -> Fut,
    Fut: Future<Output = Response>,
{
    let (reader, writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut writer = BufWriter::new(writer);

    loop {
        let mut line = String::new();
        let read = reader.read_line(&mut line).await?;
        if read == 0 {
            return Ok(());
        }
        if read > MAX_FRAME_BYTES {
            let response = Response::err(
                0,
                ApiError::new(ErrorCode::BadRequest, "request frame exceeds 1 MiB"),
            );
            write_response(&mut writer, &response).await?;
            return Ok(());
        }

        let request = match serde_json::from_str::<Request>(line.trim_end()) {
            Ok(request) => request,
            Err(error) => {
                let response = Response::err(
                    0,
                    ApiError::new(ErrorCode::BadRequest, format!("invalid request: {error}")),
                );
                write_response(&mut writer, &response).await?;
                return Ok(());
            }
        };

        let response = handler(request).await;
        write_response(&mut writer, &response).await?;
    }
}

async fn write_response<W>(writer: &mut W, response: &Response) -> std::io::Result<()>
where
    W: AsyncWriteExt + Unpin,
{
    let mut encoded = serde_json::to_string(response).map_err(std::io::Error::other)?;
    encoded.push('\n');
    writer.write_all(encoded.as_bytes()).await?;
    writer.flush().await
}

//! IPC between the lekima daemon and every other client.
//!
//! One protocol, three audiences:
//!
//! - the TUI, which wants typed replies;
//! - the CLI, which wants stable JSON;
//! - code agents, which want the same stable JSON over a socket that outlives
//!   their invocation.

pub mod client;
pub mod protocol;
pub mod server;

pub use client::{IpcError, call, call_on, is_running};
pub use protocol::{
    ApiError, Command, ErrorCode, PlayTarget, Reply, Request, Response, MAX_FRAME_BYTES,
};
pub use server::serve_connection;

//! Application layer.
//!
//! [`Player`] is the only writer of playback state. It coordinates the two
//! ports it is given — a [`MusicService`] and an [`AudioEngine`] — and exposes
//! intents (`play`, `next`, `seek`, …) rather than raw state mutations. Every
//! frontend, including the TUI and the CLI, talks to this layer.

mod player;

pub use player::Player;

//! Playback orchestration.

use std::sync::Arc;

use lekima_domain::{
    AudioEngine, DomainError, MusicService, PlaybackState, PlaybackStatus, Quality, Queue,
    RepeatMode, Result, Track, TrackId,
};
use tokio::sync::Mutex;

/// What should be loaded into the queue.
#[derive(Debug, Clone)]
pub enum PlayRequest {
    Tracks(Vec<Track>),
    /// Jump to an existing queue position.
    Index(usize),
}

struct Inner {
    queue: Queue,
    status: PlaybackStatus,
    volume: f32,
    muted: bool,
    repeat: RepeatMode,
    shuffle: bool,
    position_ms: u64,
}

/// Owns queue and transport state for the daemon.
pub struct Player {
    music: Arc<dyn MusicService>,
    audio: Arc<dyn AudioEngine>,
    quality: Quality,
    inner: Mutex<Inner>,
}

impl Player {
    #[must_use]
    pub fn new(
        music: Arc<dyn MusicService>,
        audio: Arc<dyn AudioEngine>,
        quality: Quality,
        volume: f32,
    ) -> Self {
        let volume = volume.clamp(0.0, 1.0);
        let _ = audio.set_volume(volume);
        Self {
            music,
            audio,
            quality,
            inner: Mutex::new(Inner {
                queue: Queue::default(),
                status: PlaybackStatus::Stopped,
                volume,
                muted: false,
                repeat: RepeatMode::Off,
                shuffle: false,
                position_ms: 0,
            }),
        }
    }

    #[must_use]
    pub fn music(&self) -> &Arc<dyn MusicService> {
        &self.music
    }

    /// Immutable view of the current state.
    pub async fn snapshot(&self) -> PlaybackState {
        let inner = self.inner.lock().await;
        let mut state = PlaybackState {
            status: inner.status,
            track: inner.queue.current().cloned(),
            position_ms: if inner.status == PlaybackStatus::Stopped {
                0
            } else {
                self.audio.position_ms().max(inner.position_ms)
            },
            volume: inner.volume,
            muted: inner.muted,
            repeat: inner.repeat,
            shuffle: inner.shuffle,
            queue_length: inner.queue.len(),
            queue_index: inner.queue.current_index(),
        };
        if state.status != PlaybackStatus::Stopped
            && state.position_ms == 0
            && inner.position_ms > 0
        {
            state.position_ms = inner.position_ms;
        }
        state
    }

    /// Replaces the queue and starts the first track.
    pub async fn play(&self, request: PlayRequest) -> Result<PlaybackState> {
        {
            let mut inner = self.inner.lock().await;
            match request {
                PlayRequest::Tracks(tracks) => {
                    if tracks.is_empty() {
                        return Err(DomainError::InvalidInput(
                            "nothing to play: queue would be empty".to_owned(),
                        ));
                    }
                    inner.queue.replace(tracks);
                }
                PlayRequest::Index(index) => {
                    if inner.queue.jump(index).is_none() {
                        return Err(DomainError::NotFound(format!("queue index {index}")));
                    }
                }
            }
        }
        self.load_current().await?;
        Ok(self.snapshot().await)
    }

    /// Appends tracks, optionally as "play next".
    pub async fn enqueue(&self, tracks: Vec<Track>, next: bool) -> Result<()> {
        if tracks.is_empty() {
            return Err(DomainError::InvalidInput(
                "no tracks to enqueue".to_owned(),
            ));
        }
        let should_start = {
            let mut inner = self.inner.lock().await;
            let was_idle = inner.queue.is_empty();
            if next {
                for track in tracks.into_iter().rev() {
                    inner.queue.insert_next(track);
                }
            } else {
                inner.queue.extend(tracks);
            }
            was_idle
        };
        if should_start {
            self.load_current().await?;
        }
        Ok(())
    }

    pub async fn queue(&self) -> (Vec<Track>, Option<usize>) {
        let inner = self.inner.lock().await;
        (inner.queue.tracks().to_vec(), inner.queue.current_index())
    }

    pub async fn clear_queue(&self) -> Result<()> {
        let mut inner = self.inner.lock().await;
        inner.queue.clear();
        inner.status = PlaybackStatus::Stopped;
        inner.position_ms = 0;
        drop(inner);
        self.audio.stop()
    }

    /// Loads the queue's current track into the audio engine.
    async fn load_current(&self) -> Result<()> {
        let track = {
            let inner = self.inner.lock().await;
            inner
                .queue
                .current()
                .cloned()
                .ok_or_else(|| DomainError::NotFound("current track".to_owned()))?
        };

        let url = self.music.stream_url(track.id, self.quality).await?;
        if let Err(error) = self.audio.play_url(&url).await {
            let mut inner = self.inner.lock().await;
            inner.status = PlaybackStatus::Stopped;
            return Err(error);
        }

        let mut inner = self.inner.lock().await;
        inner.status = PlaybackStatus::Playing;
        inner.position_ms = 0;
        let gain = if inner.muted { 0.0 } else { inner.volume };
        let _ = self.audio.set_volume(gain);
        tracing::debug!(track = %track.id, "playback started");
        Ok(())
    }

    pub async fn pause(&self) -> Result<()> {
        let mut inner = self.inner.lock().await;
        if inner.status == PlaybackStatus::Playing {
            self.audio.pause()?;
            inner.status = PlaybackStatus::Paused;
            inner.position_ms = self.audio.position_ms();
        }
        Ok(())
    }

    pub async fn resume(&self) -> Result<()> {
        let mut inner = self.inner.lock().await;
        if inner.status == PlaybackStatus::Paused {
            self.audio.resume()?;
            inner.status = PlaybackStatus::Playing;
        } else if inner.status == PlaybackStatus::Stopped && !inner.queue.is_empty() {
            drop(inner);
            return self.load_current().await;
        }
        Ok(())
    }

    pub async fn toggle(&self) -> Result<()> {
        match self.snapshot().await.status {
            PlaybackStatus::Playing => self.pause().await,
            PlaybackStatus::Paused | PlaybackStatus::Stopped => self.resume().await,
        }
    }

    pub async fn stop(&self) -> Result<()> {
        let mut inner = self.inner.lock().await;
        self.audio.stop()?;
        inner.status = PlaybackStatus::Stopped;
        inner.position_ms = 0;
        Ok(())
    }

    /// Advances to the next track. Returns `None` at the end of the queue.
    pub async fn next(&self) -> Result<Option<Track>> {
        let advanced = {
            let mut inner = self.inner.lock().await;
            let repeat = inner.repeat;
            inner.queue.advance(repeat).cloned()
        };
        match advanced {
            Some(track) => {
                self.load_current().await?;
                Ok(Some(track))
            }
            None => {
                self.stop().await?;
                Ok(None)
            }
        }
    }

    pub async fn previous(&self) -> Result<Option<Track>> {
        {
            let mut inner = self.inner.lock().await;
            let repeat = inner.repeat;
            inner.queue.rewind(repeat);
        }
        self.load_current().await?;
        Ok(self.snapshot().await.track)
    }

    pub async fn seek(&self, position_ms: u64) -> Result<()> {
        self.audio.seek(position_ms)?;
        let mut inner = self.inner.lock().await;
        inner.position_ms = position_ms;
        Ok(())
    }

    pub async fn set_volume(&self, level: f32) -> Result<()> {
        let level = level.clamp(0.0, 1.0);
        let mut inner = self.inner.lock().await;
        inner.volume = level;
        let gain = if inner.muted { 0.0 } else { level };
        self.audio.set_volume(gain)?;
        Ok(())
    }

    pub async fn toggle_mute(&self) -> Result<bool> {
        let mut inner = self.inner.lock().await;
        inner.muted = !inner.muted;
        let gain = if inner.muted { 0.0 } else { inner.volume };
        self.audio.set_volume(gain)?;
        Ok(inner.muted)
    }

    pub async fn cycle_repeat(&self) -> RepeatMode {
        let mut inner = self.inner.lock().await;
        inner.repeat = inner.repeat.cycle();
        inner.repeat
    }

    pub async fn set_shuffle(&self, enabled: bool) -> Result<()> {
        self.inner.lock().await.shuffle = enabled;
        Ok(())
    }

    /// Called periodically by the daemon to detect the end of a track.
    ///
    /// Returns the newly started track when playback rolled over.
    pub async fn tick(&self) -> Result<Option<Track>> {
        let (finished, playing) = {
            let inner = self.inner.lock().await;
            (
                self.audio.is_finished(),
                inner.status == PlaybackStatus::Playing && self.audio.has_track(),
            )
        };
        if finished && playing {
            tracing::debug!("track ended, advancing");
            return self.next().await;
        }
        Ok(None)
    }

    pub async fn remove_current(&self) -> Result<()> {
        {
            let mut inner = self.inner.lock().await;
            inner.queue.remove_current();
        }
        if self.inner.lock().await.queue.is_empty() {
            self.stop().await?;
        } else {
            self.load_current().await?;
        }
        Ok(())
    }

    /// Resolves track ids to full metadata, rejecting unknown ids.
    pub async fn resolve_tracks(&self, ids: &[TrackId]) -> Result<Vec<Track>> {
        let tracks = self.music.tracks(ids).await?;
        if tracks.is_empty() {
            return Err(DomainError::NotFound("no tracks matched".to_owned()));
        }
        Ok(tracks)
    }
}

#[cfg(test)]
mod tests {
    use std::sync::{
        Arc, Mutex,
        atomic::{AtomicBool, AtomicU64, Ordering},
    };

    use async_trait::async_trait;
    use lekima_domain::{
        Album, Artist, AudioEngine, MusicService, PlaybackStatus, Playlist, PlaylistId, Quality,
        Result, SearchKind, SearchResults, Track, TrackId, UserId, UserProfile,
    };

    use super::{PlayRequest, Player};

    fn track(id: u64) -> Track {
        Track {
            id: TrackId(id),
            name: format!("song-{id}"),
            artists: vec![Artist {
                id: 1.into(),
                name: "artist".to_owned(),
            }],
            album: Some(Album {
                id: 1.into(),
                name: "album".to_owned(),
                cover_url: None,
            }),
            duration_ms: 1_000,
        }
    }

    struct StubMusic;

    #[async_trait]
    impl MusicService for StubMusic {
        async fn search(
            &self,
            _: &str,
            _: SearchKind,
            _: u32,
            _: u32,
        ) -> Result<SearchResults> {
            Ok(SearchResults::default())
        }

        async fn tracks(&self, ids: &[TrackId]) -> Result<Vec<Track>> {
            Ok(ids.iter().map(|id| track(id.0)).collect())
        }

        async fn stream_url(&self, id: TrackId, _: Quality) -> Result<String> {
            Ok(format!("https://example.test/{id}.mp3"))
        }

        async fn playlists(&self, _: Option<UserId>) -> Result<Vec<Playlist>> {
            Ok(Vec::new())
        }

        async fn playlist_tracks(&self, _: PlaylistId) -> Result<Vec<Track>> {
            Ok(Vec::new())
        }

        async fn current_user(&self) -> Result<Option<UserProfile>> {
            Ok(None)
        }

        async fn lyrics(&self, _: TrackId) -> Result<String> {
            Ok(String::new())
        }
    }

    #[derive(Default)]
    struct StubAudio {
        playing: AtomicBool,
        finished: AtomicBool,
        position: AtomicU64,
        volume: Mutex<f32>,
        last_url: Mutex<Option<String>>,
    }

    #[async_trait]
    impl AudioEngine for StubAudio {
        async fn play_url(&self, url: &str) -> Result<()> {
            *self.last_url.lock().unwrap() = Some(url.to_owned());
            self.playing.store(true, Ordering::SeqCst);
            self.finished.store(false, Ordering::SeqCst);
            Ok(())
        }

        fn pause(&self) -> Result<()> {
            self.playing.store(false, Ordering::SeqCst);
            Ok(())
        }

        fn resume(&self) -> Result<()> {
            self.playing.store(true, Ordering::SeqCst);
            Ok(())
        }

        fn stop(&self) -> Result<()> {
            self.playing.store(false, Ordering::SeqCst);
            self.finished.store(false, Ordering::SeqCst);
            Ok(())
        }

        fn seek(&self, position_ms: u64) -> Result<()> {
            self.position.store(position_ms, Ordering::SeqCst);
            Ok(())
        }

        fn set_volume(&self, gain: f32) -> Result<()> {
            *self.volume.lock().unwrap() = gain;
            Ok(())
        }

        fn position_ms(&self) -> u64 {
            self.position.load(Ordering::SeqCst)
        }

        fn is_finished(&self) -> bool {
            self.finished.load(Ordering::SeqCst)
        }

        fn has_track(&self) -> bool {
            self.playing.load(Ordering::SeqCst)
        }
    }

    fn player() -> (Player, Arc<StubAudio>) {
        let audio = Arc::new(StubAudio::default());
        let player = Player::new(
            Arc::new(StubMusic),
            audio.clone(),
            Quality::Exhigh,
            0.5,
        );
        (player, audio)
    }

    #[tokio::test]
    async fn play_loads_the_first_track_and_reports_playing() {
        let (player, audio) = player();
        let state = player
            .play(PlayRequest::Tracks(vec![track(1), track(2)]))
            .await
            .unwrap();
        assert_eq!(state.status, PlaybackStatus::Playing);
        assert_eq!(state.track.unwrap().id, TrackId(1));
        assert!(audio.last_url.lock().unwrap().is_some());
    }

    #[tokio::test]
    async fn empty_queue_is_rejected() {
        let (player, _) = player();
        assert!(player.play(PlayRequest::Tracks(Vec::new())).await.is_err());
    }

    #[tokio::test]
    async fn finished_track_advances_and_stops_at_the_end() {
        let (player, audio) = player();
        player
            .play(PlayRequest::Tracks(vec![track(1), track(2)]))
            .await
            .unwrap();
        audio.finished.store(true, Ordering::SeqCst);
        let rolled = player.tick().await.unwrap();
        assert_eq!(rolled.unwrap().id, TrackId(2));

        audio.finished.store(true, Ordering::SeqCst);
        assert!(player.tick().await.unwrap().is_none());
        assert_eq!(player.snapshot().await.status, PlaybackStatus::Stopped);
    }

    #[tokio::test]
    async fn mute_keeps_the_stored_volume() {
        let (player, audio) = player();
        player.set_volume(0.9).await.unwrap();
        player.toggle_mute().await.unwrap();
        assert_eq!(*audio.volume.lock().unwrap(), 0.0);
        assert!((player.snapshot().await.volume - 0.9).abs() < f32::EPSILON);
        player.toggle_mute().await.unwrap();
        assert_eq!(*audio.volume.lock().unwrap(), 0.9);
    }

    #[tokio::test]
    async fn repeat_cycles_off_all_one() {
        let (player, _) = player();
        assert_eq!(player.cycle_repeat().await.as_str(), "all");
        assert_eq!(player.cycle_repeat().await.as_str(), "one");
        assert_eq!(player.cycle_repeat().await.as_str(), "off");
    }
}

