//! NetEase Cloud Music adapter.
//!
//! This crate is the only place that knows about `ncmapi`. It translates
//! provider payloads into the domain vocabulary and provider failures into
//! [`lekima_domain::DomainError`]. Pure mapping functions live in [`map`] so
//! they can be tested against fixtures without a network.

mod map;
mod service;

pub use service::{NcmMusicService, NcmOptions};

//! Provider → domain mapping.
//!
//! Everything here is pure: fixtures in, domain values out. The provider is
//! allowed to omit fields, so defaults are explicit and every field that can be
//! absent is documented.

use lekima_domain as domain;
use ncmapi as provider;

pub(crate) fn track(track: provider::Track) -> domain::Track {
    let album = if track.album.id == 0 && track.album.name.is_empty() {
        None
    } else {
        Some(domain::Album {
            id: domain::AlbumId(track.album.id),
            name: track.album.name,
            cover_url: (!track.album.pic_url.is_empty()).then_some(track.album.pic_url),
        })
    };

    domain::Track {
        id: domain::TrackId(track.id),
        name: track.name,
        artists: track
            .artists
            .into_iter()
            .map(|artist| domain::Artist {
                id: domain::ArtistId(artist.id),
                name: artist.name,
            })
            .collect(),
        album,
        duration_ms: u64::from(track.duration),
    }
}

pub(crate) fn search_results(body: provider::SearchBody) -> domain::SearchResults {
    let tracks: Vec<_> = body.result.songs.into_iter().map(track).collect();
    domain::SearchResults {
        total: u64::try_from(tracks.len()).unwrap_or(u64::MAX),
        tracks,
        playlists: Vec::new(),
        artists: Vec::new(),
    }
}

pub(crate) fn playlist(playlist: provider::Playlist) -> domain::Playlist {
    domain::Playlist {
        id: domain::PlaylistId(playlist.id),
        name: playlist.name,
        description: playlist.description.unwrap_or_default(),
        track_count: 0,
        cover_url: None,
        owner: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maps_a_complete_track() {
        let raw = serde_json::json!({
            "id": 42,
            "name": "mota",
            "artists": [{"id": 7, "name": "Zhang"}],
            "album": {"id": 9, "name": "Album", "picUrl": "https://img/9.jpg"},
            "duration": 245_000
        });
        let provider_track: provider::Track = serde_json::from_value(raw).unwrap();
        let track = track(provider_track);
        assert_eq!(track.id, domain::TrackId(42));
        assert_eq!(track.artist_names(), "Zhang");
        assert_eq!(track.album_name(), "Album");
        assert_eq!(track.duration_ms, 245_000);
        assert_eq!(
            track.album.unwrap().cover_url.as_deref(),
            Some("https://img/9.jpg")
        );
    }

    #[test]
    fn tolerates_missing_album_and_artist_fields() {
        let raw = serde_json::json!({
            "id": 1,
            "name": "nameless",
            "album": {},
            "artists": []
        });
        let provider_track: provider::Track = serde_json::from_value(raw).unwrap();
        let track = track(provider_track);
        assert!(track.album.is_none());
        assert_eq!(track.artist_names(), "Unknown artist");
        assert_eq!(track.duration_label(), "--:--");
    }

    #[test]
    fn maps_search_payloads() {
        let raw = serde_json::json!({
            "code": 200,
            "result": {
                "songs": [{"id": 1, "name": "a", "artists": [], "album": {}, "duration": 1000}],
                "hasMore": true
            }
        });
        let response: provider::ApiResponse<provider::SearchBody> =
            serde_json::from_value(raw).unwrap();
        let results = search_results(response.body);
        assert_eq!(results.tracks.len(), 1);
        assert_eq!(results.total, 1);
    }

    #[test]
    fn maps_playlists_without_optional_fields() {
        let raw = serde_json::json!({"id": 5, "name": "Late night"});
        let playlist: provider::Playlist = serde_json::from_value(raw).unwrap();
        let playlist = playlist(playlist);
        assert_eq!(playlist.id, domain::PlaylistId(5));
        assert_eq!(playlist.track_count, 0);
        assert_eq!(playlist.description, "");
    }
}

//! `MusicService` implemented over `ncmapi`.

use std::{path::PathBuf, time::Duration};

use async_trait::async_trait;
use lekima_domain::{
    self as domain, DomainError, MusicService, PlaylistId, Quality, SearchKind, TrackId, UserId,
    UserProfile,
};
use ncmapi::{
    ApiResponse, NcmClient, Page, SearchKind as ProviderSearchKind, SearchQuery,
    TrackId as ProviderTrackId, UserId as ProviderUserId,
};

use crate::map;

/// Construction inputs for [`NcmMusicService`].
#[derive(Debug, Clone)]
pub struct NcmOptions {
    /// Where the session cookie header is read from and written to.
    pub cookie_path: PathBuf,
    /// Enables the SDK's short-lived response cache.
    pub cache: bool,
    pub cache_ttl: Duration,
}

impl NcmOptions {
    #[must_use]
    pub fn new(cookie_path: impl Into<PathBuf>) -> Self {
        Self {
            cookie_path: cookie_path.into(),
            cache: true,
            cache_ttl: Duration::from_secs(180),
        }
    }
}

/// NetEase-backed catalogue and account service.
pub struct NcmMusicService {
    client: NcmClient,
}

impl NcmMusicService {
    /// Builds the service. Fails eagerly on invalid local configuration.
    ///
    /// # Errors
    ///
    /// Returns a domain error when the SDK cannot be constructed (for example a
    /// cookie file with invalid permissions content).
    pub fn new(options: NcmOptions) -> domain::Result<Self> {
        let client = NcmClient::builder()
            .cache(options.cache)
            .cache_ttl(options.cache_ttl)
            .cookie_path(options.cookie_path)
            .build()
            .map_err(provider_error)?;
        Ok(Self { client })
    }
}

fn ensure_success<T>(response: ApiResponse<T>) -> domain::Result<ApiResponse<T>> {
    match response.code {
        200 => Ok(response),
        301 => Err(DomainError::AuthenticationRequired(
            "the music provider rejected the session; run `lekima login`".to_owned(),
        )),
        code => Err(DomainError::Unavailable(format!(
            "the music provider returned code {code}"
        ))),
    }
}

fn provider_error(error: ncmapi::Error) -> DomainError {
    use ncmapi::Error;
    match error {
        Error::InvalidInput { field, reason } => {
            DomainError::InvalidInput(format!("{field}: {reason}"))
        }
        Error::Http(source) => DomainError::Unavailable(format!("provider request failed: {source}")),
        Error::CookiePersistence { operation, source } => DomainError::Unavailable(format!(
            "session storage failed while {operation}: {source}"
        )),
        other => DomainError::Unavailable(format!("provider protocol error: {other}")),
    }
}

fn provider_kind(kind: SearchKind) -> ProviderSearchKind {
    match kind {
        SearchKind::Track => ProviderSearchKind::Song,
        SearchKind::Album => ProviderSearchKind::Album,
        SearchKind::Artist => ProviderSearchKind::Artist,
        SearchKind::Playlist => ProviderSearchKind::Playlist,
    }
}

fn map_page(limit: u32, offset: u32) -> domain::Result<(u16, u32)> {
    if limit == 0 {
        return Err(DomainError::InvalidInput(
            "search limit must be greater than zero".to_owned(),
        ));
    }
    let limit = u16::try_from(limit.min(100))
        .map_err(|_| DomainError::InvalidInput("search limit is too large".to_owned()))?;
    Ok((limit, offset))
}

#[async_trait]
impl MusicService for NcmMusicService {
    async fn search(
        &self,
        query: &str,
        kind: SearchKind,
        limit: u32,
        offset: u32,
    ) -> domain::Result<domain::SearchResults> {
        let (limit, offset) = map_page(limit, offset)?;
        let query = SearchQuery::new(query)
            .map_err(provider_error)?
            .kind(provider_kind(kind))
            .page(limit, offset)
            .map_err(provider_error)?;

        let response = self
            .client
            .discovery()
            .search(query)
            .await
            .map_err(provider_error)?;
        let response = ensure_success(response)?;
        Ok(map::search_results(response.body))
    }

    async fn tracks(&self, ids: &[TrackId]) -> domain::Result<Vec<domain::Track>> {
        let provider_ids: Vec<_> = ids.iter().copied().map(ProviderTrackId).collect();
        let response = self
            .client
            .library()
            .tracks(&provider_ids)
            .await
            .map_err(provider_error)?;
        let response = ensure_success(response)?;
        Ok(response.body.songs.into_iter().map(map::track).collect())
    }

    async fn stream_url(&self, id: TrackId, _quality: Quality) -> domain::Result<String> {
        let response = self
            .client
            .library()
            .stream_urls(&[ProviderTrackId(id.0)])
            .await
            .map_err(provider_error)?;
        let response = ensure_success(response)?;
        response
            .body
            .data
            .into_iter()
            .find_map(|stream| stream.url)
            .filter(|url| !url.is_empty())
            .ok_or_else(|| {
                DomainError::Unsupported(format!(
                    "track {id} has no playable stream (VIP, region, or removed)"
                ))
            })
    }

    async fn playlists(
        &self,
        user: Option<UserId>,
    ) -> domain::Result<Vec<domain::Playlist>> {
        let user_id = match user {
            Some(user) => user,
            None => {
                let profile = self.current_user().await?.ok_or_else(|| {
                    DomainError::AuthenticationRequired(
                        "sign in to list your playlists".to_owned(),
                    )
                })?;
                profile.id
            }
        };

        let page = Page::first(200).map_err(provider_error)?;
        let response = self
            .client
            .profile()
            .playlists(ProviderUserId(user_id.0), page)
            .await
            .map_err(provider_error)?;
        let response = ensure_success(response)?;
        Ok(response
            .body
            .playlist
            .into_iter()
            .map(map::playlist)
            .collect())
    }

    async fn playlist_tracks(&self, id: PlaylistId) -> domain::Result<Vec<domain::Track>> {
        let _ = id;
        Err(DomainError::Unsupported(
            "playlist tracks require ncmapi 1.1 (`/api/v6/playlist/detail`)".to_owned(),
        ))
    }

    async fn current_user(&self) -> domain::Result<Option<UserProfile>> {
        let response = self
            .client
            .profile()
            .current()
            .await
            .map_err(provider_error)?;
        if response.code == 301 {
            return Ok(None);
        }
        let response = ensure_success(response)?;
        Ok(response.body.profile.map(|profile| UserProfile {
            id: UserId(profile.user_id),
            nickname: profile.nickname,
            avatar_url: None,
        }))
    }

    async fn lyrics(&self, id: TrackId) -> domain::Result<String> {
        let _ = id;
        Err(DomainError::Unsupported(
            "lyrics require ncmapi 1.1 (`/api/song/lyric`)".to_owned(),
        ))
    }
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use lekima_domain::{MusicService, PlaylistId, TrackId};

    use super::{NcmMusicService, NcmOptions};

    fn service() -> NcmMusicService {
        NcmMusicService::new(NcmOptions {
            cookie_path: std::env::temp_dir().join("lekima-test-cookies"),
