                    Ok(decoder) => { player.append(decoder); player.play(); shared.set_loaded(true); shared.set_finished(false); shared.set_position(0); ack.send(Ok(())) }
                    Err(e) => { shared.set_loaded(false); ack.send(Err(format!("{e}"))) }
                }
            }
            Ok(Command::Pause) => { player.pause(); }
            Ok(Command::Resume) => { player.play(); }
            Ok(Command::Stop) => { player.stop(); shared.set_loaded(false); shared.set_finished(false); shared.set_position(0); }
            Ok(Command::Seek(ms)) => { player.try_seek(Duration::from_millis(ms)) ...}
            Ok(Command::Volume(g)) => { player.set_volume(g) }
