async fn event_loop(terminal: &mut ratatui::DefaultTerminal, socket: PathBuf) -> Result<()> {
  let mut app = App::new();
  let mut keys = spawn_key_reader();
  let (tx, mut replies) = unbounded_channel::<Result<Reply, IpcError>>();
  let mut tick = tokio::time::interval(Duration::from_millis(250));
  dispatch(&socket, Command::Status, &tx); app.status_inflight = true;
  dispatch(&socket, Command::Playlists, &tx);
  dispatch(&socket, Command::Queue, &tx);
  dispatch(&socket, Command::Whoami, &tx);
  loop {
    app.clamp();
    terminal.draw(|frame| ui::draw(frame, &mut app))?;
    tokio::select! {
      key = keys.recv() => match key {
         Some(key) => match app.handle_key(key) { ... }
         None => break,
      },
      Some(result) = replies.recv() => {
         if let Action::Call(cmd) = app.apply(result) { dispatch(...) }
      }
      _ = tick.tick() => {
         if !app.status_inflight && !app.daemon_down {
            app.status_inflight = true;
            dispatch(&socket, Command::Status, &tx);
         }
      }
    }
  }
  Ok(())
}
