//! Rendering. `draw` is a pure function of [`App`] plus the current frame area.

use lekima_domain::{PlaybackStatus, Track, format_duration_ms};
use ratatui::{
    Frame,
    layout::{Constraint, Flex, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span, Text},
    widgets::{Block, Clear, Gauge, List, ListItem, ListState, Paragraph, Row, Table, TableState},
};

use crate::app::{App, Focus, Mode};

pub fn draw(frame: &mut Frame, app: &mut App) {
    app.clamp();
    let [header, body, footer] = Layout::vertical([
        Constraint::Length(5),
        Constraint::Min(5),
        Constraint::Length(1),
    ])
    .areas(frame.area());

    draw_header(frame, app, header);
    draw_body(frame, app, body);
    draw_footer(frame, app, footer);

    match app.mode {
        Mode::Help => draw_help(frame, frame.area()),
        _ => {}
    }
}

fn draw_header(frame: &mut Frame, app: &App, area: Rect) {
    let block = Block::bordered()
        .title(Line::from(vec![
            Span::styled(" lekima ", Style::new().add_modifier(Modifier::BOLD)),
            Span::styled(
                format!(" {} ", app.source),
                Style::new().fg(Color::DarkGray),
            ),
        ]))
        .border_style(Style::new().fg(Color::DarkGray));
    let inner = block.inner(area);
    frame.render_widget(block, area);

    let [info_area, gauge_area] =
        Layout::vertical([Constraint::Length(2), Constraint::Length(1)]).areas(inner);

    let (icon, title, subtitle) = match (&app.status.track, app.status.status) {
        (Some(track), status) => (
            status_icon(status),
            format!(" {} ", track.name),
            format!(
                "{} · {}",
                track.artist_names(),
                if track.album_name().is_empty() {
                    app.source.clone()
                } else {
                    track.album_name().to_owned()
                }
            ),
        ),
        (None, _) => (
            " ■ ",
            " nothing playing ".to_owned(),
            "press / to search, or :play <query>".to_owned(),
        ),
    };

    let info = Paragraph::new(Text::from(vec![
        Line::from(vec![
            Span::styled(icon, Style::new().fg(accent(app))),
            Span::styled(title, Style::new().add_modifier(Modifier::BOLD)),
        ]),
        Line::from(Span::styled(subtitle, Style::new().fg(Color::Gray))),
    ]));
    frame.render_widget(info, info_area);

    let duration = app
        .status
        .track
        .as_ref()
        .map_or(0, |track| track.duration_ms.max(1));
    let ratio = (app.status.position_ms as f64 / duration as f64).clamp(0.0, 1.0);
    let label = format!(
        "{} / {}   vol {:.0}%   repeat {}   queue {}",
        format_duration_ms(app.status.position_ms),
        format_duration_ms(duration),
        app.status.effective_volume() * 100.0,
        app.status.repeat.as_str(),
        app.status.queue_length,
    );
    let gauge = Gauge::default()
        .ratio(ratio)
        .label(Span::styled(label, Style::new().fg(Color::Gray)))
        .gauge_style(Style::new().fg(accent(app)))
        .use_unicode(true);
    frame.render_widget(gauge, gauge_area);
}

fn draw_body(frame: &mut Frame, app: &mut App, area: Rect) {
    let [sidebar, main] =
        Layout::horizontal([Constraint::Length(26), Constraint::Min(20)]).areas(area);

    draw_sidebar(frame, app, sidebar);
    match app.mode {
        Mode::Queue => draw_queue(frame, app, main),
        _ => draw_tracks(frame, app, main),
    }
}

fn draw_sidebar(frame: &mut Frame, app: &mut App, area: Rect) {
    let focused = app.focus == Focus::Sidebar && app.mode != Mode::Queue;
    let block = Block::bordered()
        .title(Line::from(" library "))
        .border_style(border_style(focused));
    let inner = block.inner(area);

    let items: Vec<ListItem> = app
        .playlists
        .iter()
        .map(|playlist| {
            let count = if playlist.track_count > 0 {
                format!(" ({})", playlist.track_count)
            } else {
                String::new()
            };
            ListItem::new(Line::from(vec![
                Span::raw(playlist.name.clone()),
                Span::styled(count, Style::new().fg(Color::DarkGray)),
            ]))
        })
        .collect();

    if items.is_empty() {
        let hint = Paragraph::new(Text::from(vec![
            Line::from(Span::styled("No playlists", Style::new().fg(Color::Gray))),
            Line::from(Span::styled(
                "run `lekima login`",
                Style::new().fg(Color::DarkGray),
            )),
        ]));
        frame.render_widget(hint, inner);
        frame.render_widget(block, area);
        return;
    }

    let list = List::new(items)
        .highlight_style(Style::new().add_modifier(Modifier::REVERSED))
        .highlight_symbol("▸ ");
    let mut state = ListState::default().with_selected(Some(app.sidebar_selection));
    frame.render_stateful_widget(list, inner, &mut state);
    frame.render_widget(block, area);
}

fn draw_tracks(frame: &mut Frame, app: &mut App, area: Rect) {
    let focused = app.focus == Focus::Main;
    let block = Block::bordered()
        .title(Line::from(format!(
            " {} · {} tracks ",
            app.source,
            app.tracks.len()
        )))
        .border_style(border_style(focused));
    let inner = block.inner(area);

    if app.tracks.is_empty() {
        let hint = Paragraph::new(Line::from(Span::styled(
            "press / to search, or Tab to the library",
            Style::new().fg(Color::Gray),
        )));
        frame.render_widget(hint, inner);
        frame.render_widget(block, area);
        return;
    }

    let playing_id = app.status.track.as_ref().map(|track| track.id);
    let rows: Vec<Row> = app
        .tracks
        .iter()
        .enumerate()
        .map(|(index, track)| {
            let marker = if Some(track.id) == playing_id {
                status_icon(app.status.status)
            } else {
                " "
            };
            Row::new(vec![
                format!("{marker} {}", index + 1),
                track.name.clone(),
                track.artist_names(),
                track.duration_label(),
            ])
        })
        .collect();

    let widths = [
        Constraint::Length(5),
        Constraint::Percentage(45),
        Constraint::Percentage(35),
        Constraint::Length(7),
    ];
    let table = Table::new(rows, widths)
        .header(
            Row::new(vec!["#", "TITLE", "ARTIST", "TIME"])
                .style(Style::new().add_modifier(Modifier::BOLD)),
        )
        .row_highlight_style(Style::new().add_modifier(Modifier::REVERSED))
        .highlight_symbol("▸ ");

    let mut state = TableState::default().with_selected(if focused {
        Some(app.main_selection)
    } else {
        None
    });
    frame.render_stateful_widget(table, inner, &mut state);
    frame.render_widget(block, area);
}

fn draw_queue(frame: &mut Frame, app: &mut App, area: Rect) {
    let block = Block::bordered()
        .title(Line::from(format!(" queue · {} ", app.queue.len())))
        .border_style(border_style(true));
    let inner = block.inner(area);

    if app.queue.is_empty() {
        frame.render_widget(
            Paragraph::new(Line::from(Span::styled(
                "queue is empty",
                Style::new().fg(Color::Gray),
            ))),
            inner,
        );
        frame.render_widget(block, area);
        return;
    }

    let current = app.status.queue_index;
    let items: Vec<ListItem> = app
        .queue
        .iter()
        .enumerate()
        .map(|(index, track)| {
            let marker = if Some(index) == current { "▶" } else { " " };
            ListItem::new(Line::from(vec![
                Span::styled(format!("{marker} "), Style::new().fg(accent(app))),
                Span::raw(track_label(track)),
            ]))
        })
        .collect();

    let list = List::new(items)
        .highlight_style(Style::new().add_modifier(Modifier::REVERSED))
        .highlight_symbol("▸ ");
    let mut state = ListState::default().with_selected(Some(app.queue_selection));
    frame.render_stateful_widget(list, inner, &mut state);
    frame.render_widget(block, area);
}

fn draw_footer(frame: &mut Frame, app: &App, area: Rect) {
    let (mode, hints) = match app.mode {
        Mode::Normal => (
            " NORMAL ",
            "j/k move · ⏎ play · space pause · / search · : command · Q queue · ? help",
        ),
        Mode::Search => (" / ", "type to search · ⏎ run · esc cancel"),
        Mode::Command => (" : ", "q · play <query> · vol <0-100> · queue · help"),
        Mode::Help => (" HELP ", "? or esc to close"),
        Mode::Queue => (" QUEUE ", "j/k move · ⏎ jump · esc close"),
    };

    let mut spans = vec![
        Span::styled(
            mode,
            Style::new()
                .fg(Color::Black)
                .bg(accent(app))
                .add_modifier(Modifier::BOLD),
        ),
        Span::raw(" "),
    ];

    if matches!(app.mode, Mode::Search | Mode::Command) {
        spans.push(Span::styled(
            format!("{}{}", app.input, "▌"),
            Style::new().add_modifier(Modifier::BOLD),
        ));
    } else {
        spans.push(Span::styled(
            hints,
            Style::new().fg(Color::DarkGray),
        ));
    }

    if let Some(message) = &app.message {
        spans.push(Span::raw("  ·  "));
        spans.push(Span::styled(
            message.text.clone(),
            if message.error {
                Style::new().fg(Color::Red)
            } else {
                Style::new().fg(Color::Green)
            },
        ));
    }
    if app.daemon_down {
        spans.push(Span::styled(
            "  ·  daemon offline (R to start)",
            Style::new().fg(Color::Yellow),
        ));
    }

    frame.render_widget(Paragraph::new(Line::from(spans)), area);
}

fn draw_help(frame: &mut Frame, area: Rect) {
    let popup = centered(area, 68, 70);
    frame.render_widget(Clear, popup);
    let block = Block::bordered()
        .title(Line::from(" keys "))
        .border_style(Style::new().fg(Color::Gray));

    let lines = vec![
        Line::from(Span::styled("MOVEMENT", Style::new().add_modifier(Modifier::BOLD))),
        Line::from("  j / k        down / up"),
        Line::from("  ctrl-d/u     half page"),
        Line::from("  g / G        top / bottom"),
        Line::from("  tab          switch sidebar / list"),
        Line::from(""),
        Line::from(Span::styled("PLAYBACK", Style::new().add_modifier(Modifier::BOLD))),
        Line::from("  enter        play selection"),
        Line::from("  space        pause / resume"),
        Line::from("  n / p        next / previous"),
        Line::from("  h / l        seek -10s / +10s"),
        Line::from("  + / -        volume"),
        Line::from("  m            mute"),
        Line::from("  r            repeat off → all → one"),
        Line::from("  s            shuffle toggle"),
        Line::from("  a / A        enqueue / play next"),
        Line::from(""),
        Line::from(Span::styled("APP", Style::new().add_modifier(Modifier::BOLD))),
        Line::from("  /            search"),
        Line::from("  :            command line"),
        Line::from("  Q            queue"),
        Line::from("  ?            this help"),
        Line::from("  q / ctrl-c   quit"),
    ];
    let paragraph = Paragraph::new(Text::from(lines)).block(block);
    frame.render_widget(paragraph, popup);
}

fn centered(area: Rect, percent_x: u16, percent_y: u16) -> Rect {
    let [area] = Layout::vertical([Constraint::Percentage(percent_y)])
        .flex(Flex::Center)
        .areas(area);
    let [area] = Layout::horizontal([Constraint::Percentage(percent_x)])
        .flex(Flex::Center)
        .areas(area);
    area
}

fn track_label(track: &Track) -> String {
    format!("{} · {}", track.name, track.artist_names())
}

const fn status_icon(status: PlaybackStatus) -> &'static str {
    match status {
        PlaybackStatus::Playing => "▶",
        PlaybackStatus::Paused => "⏸",
        PlaybackStatus::Stopped => "■",
    }
}

fn accent(app: &App) -> Color {
    if app.is_playing() {
        Color::Green
    } else {
        Color::Yellow
    }
}

fn border_style(focused: bool) -> Style {
    if focused {
        Style::new().fg(Color::Gray)
    } else {
        Style::new().fg(Color::DarkGray)
    }
}

//! Keyboard-first terminal frontend.
//!
//! The TUI is a pure client: it owns no playback state, it renders replies from
//! the daemon and forwards intents. That keeps the UI responsive while the
//! network is slow and lets a CLI or an agent change what you are looking at.

pub mod app;
pub mod ui;

use std::path::{Path, PathBuf};

use crossterm::event::{Event, KeyEvent, KeyEventKind};
use lekima_ipc::{Command, IpcError, Reply, call};
use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender, unbounded_channel};

use crate::app::{Action, App};

type ReplyResult = Result<Reply, IpcError>;

#[derive(Debug, thiserror::Error)]
pub enum TuiError {
    #[error("terminal error: {0}")]
    Io(#[from] std::io::Error),
}

/// Runs the TUI until the user quits.
///
/// # Errors
///
/// Returns [`TuiError`] when the terminal cannot be drawn.
pub async fn run(socket: PathBuf) -> Result<(), TuiError> {
    let mut terminal = ratatui::init();
    let result = event_loop(&mut terminal, socket).await;
    ratatui::restore();
    result
}

async fn event_loop(
    terminal: &mut ratatui::DefaultTerminal,
    socket: PathBuf,
) -> Result<(), TuiError> {
    let mut app = App::new();
    let mut keys = spawn_key_reader();
    let (sender, mut replies) = unbounded_channel::<ReplyResult>();

    dispatch(&socket, Command::Status, &sender);
    app.status_inflight = true;
    dispatch(&socket, Command::Playlists, &sender);
    dispatch(&socket, Command::Queue, &sender);
    dispatch(&socket, Command::Whoami, &sender);

    let mut ticker = tokio::time::interval(std::time::Duration::from_millis(250));
    ticker.tick().await;

    loop {
        terminal.draw(|frame| ui::draw(frame, &mut app))?;

        tokio::select! {
            key = keys.recv() => {
                let Some(key) = key else { break };
                let action = app.handle_key(key);
                if apply_action(action, &socket, &sender, &mut app) {
                    break;
                }
            }
            reply = replies.recv() => {
                let Some(reply) = reply else { break };
                let follow_up = app.apply(reply);
                apply_action(follow_up, &socket, &sender, &mut app);
            }
            _ = ticker.tick() => {
                if !app.status_inflight && !app.daemon_down {
                    app.status_inflight = true;
                    dispatch(&socket, Command::Status, &sender);
                }
            }
        }
    }
    Ok(())
}

/// Returns `true` when the TUI should exit.
fn apply_action(
    action: Action,
    socket: &Path,
    sender: &UnboundedSender<ReplyResult>,
    app: &mut App,
) -> bool {
    match action {
        Action::None => false,
        Action::Quit => true,
        Action::Call(command) => {
            dispatch(socket, command, sender);
            false
        }
        Action::SpawnDaemon => {
            spawn_daemon();
            app.notify("starting the daemon…", false);
            false
        }
    }
}

fn dispatch(socket: &Path, command: Command, sender: &UnboundedSender<ReplyResult>) {
    let socket = socket.to_path_buf();
    let sender = sender.clone();
    tokio::spawn(async move {
        let result = call(&socket, command).await;
        let _ = sender.send(result);
    });
}

fn spawn_daemon() {
    let Ok(executable) = std::env::current_exe() else {
        return;
    };
    let _ = std::process::Command::new(executable)
        .args(["daemon", "run", "--detached"])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn();
}

fn spawn_key_reader() -> UnboundedReceiver<KeyEvent> {
    let (sender, receiver) = unbounded_channel();
    std::thread::spawn(move || loop {
        match crossterm::event::read() {
            Ok(Event::Key(key)) if key.kind == KeyEventKind::Press => {
                if sender.send(key).is_err() {
                    break;
                }
            }
            Ok(_) => {}
            Err(_) => break,
        }
    });
    receiver
}

//! Command line surface. This file is the contract with humans and agents:
//! names, flags and help text are API.

use std::path::PathBuf;

use clap::{Parser, Subcommand, ValueEnum};
use clap_complete::Shell;

#[derive(Debug, Parser)]
#[command(
    name = "lekima",
    version,
    about = "NetEase Cloud Music in your terminal — vim-first, agent-native",
    long_about = "A keyboard-driven NetEase Cloud Music player.\n\n\
                  Playback is owned by a small background daemon, so music keeps \
                  playing after the TUI closes and every command works from scripts \
                  and code agents. Use --json for machine-readable output.",
    propagate_version = true
)]
pub struct Cli {
    /// Unix socket of the player daemon.
    #[arg(long, global = true, env = "LEKIMA_SOCKET", value_name = "PATH")]
    pub socket: Option<PathBuf>,

    /// Emit one JSON object instead of human-readable output.
    #[arg(long, global = true)]
    pub json: bool,

    /// Suppress non-essential output.
    #[arg(long, short, global = true)]
    pub quiet: bool,

    #[command(subcommand)]
    pub command: TopCommand,
}

#[derive(Debug, Subcommand)]
pub enum TopCommand {
    /// Open the interactive player.
    Tui,

    /// Play a search query, track ids, or a playlist.
    Play {
        /// Search query, e.g. `lekima play bohemian rhapsody`.
        #[arg(value_name = "QUERY")]
        query: Vec<String>,

        /// Play specific track ids (repeatable).
        #[arg(long = "id", value_name = "ID")]
        ids: Vec<u64>,

        /// Play every track of a playlist.
        #[arg(long, value_name = "ID")]
        playlist: Option<u64>,
    },

    /// Pause playback.
    Pause,

    /// Resume playback.
    Resume,

    /// Toggle between playing and paused.
    Toggle,

    /// Stop playback and clear the current track.
    Stop,

    /// Play the next track.
    Next,

    /// Play the previous track.
    Prev,

    /// Seek to an absolute position or by a relative offset.
    Seek {
        /// `1:23`, `83`, `83s`, `+10s`, `-10s`, `2m`.
        #[arg(value_name = "POSITION")]
        position: String,
    },

    /// Show or change the volume.
    Volume {
        /// Percent (`70`, `70%`) or fraction (`0.7`).
        #[arg(value_name = "LEVEL")]
        level: Option<String>,

        /// Mute output.
        #[arg(long, conflicts_with = "unmute")]
        mute: bool,

        /// Unmute output.
        #[arg(long)]
        unmute: bool,
    },

    /// Inspect or modify the play queue.
    Queue {
        #[command(subcommand)]
        action: Option<QueueCommand>,
    },

    /// Search the catalogue.
    Search {
        #[arg(value_name = "QUERY", required = true)]
        query: Vec<String>,

        /// What to search for.
        #[arg(long, value_enum, default_value_t = Kind::Track)]
        kind: Kind,

        #[arg(long, default_value_t = 40)]
        limit: u32,

        #[arg(long, default_value_t = 0)]
        offset: u32,
    },

    /// List or open playlists.
    Playlist {
        #[command(subcommand)]
        action: PlaylistCommand,
    },

    /// Print lyrics for a track (requires ncmapi 1.1).
    Lyrics {
        #[arg(long, value_name = "ID")]
        id: Option<u64>,
    },

    /// Show the current playback state.
    Status,

    /// Save a session cookie so the provider accepts requests.
    Login {
        /// File containing the cookie header; `-` reads stdin.
        #[arg(long, value_name = "PATH")]
        cookie_file: Option<PathBuf>,

        /// Start the QR flow in the terminal (not available yet).
        #[arg(long)]
        qr: bool,
    },

    /// Remove the stored session.
    Logout,

    /// Show the signed-in account.
    Whoami,

    /// Manage the background player daemon.
    Daemon {
        #[command(subcommand)]
        action: DaemonCommand,
    },

    /// Check installation, configuration, session and audio device.
    Doctor,

    /// Machine-readable command catalogue.
    Capabilities,

    /// Generate shell completions.
    Completions {
        #[arg(value_enum)]
        shell: Shell,
    },
}

#[derive(Debug, Subcommand)]
pub enum QueueCommand {
    /// List queued tracks.
    List,
