//! Output and process-exit policy.
//!
//! Human output is for people; `--json` is the stable agent contract:
//!
//! ```json
//! {"ok":true,"data":{…}}
//! {"ok":false,"error":{"code":"unauthorized","message":"…"}}
//! ```

use lekima_domain::{PlaybackState, Playlist, SearchResults, Track};
use lekima_ipc::{ApiError, ErrorCode, IpcError, Reply};
use serde::Serialize;
use serde_json::Value;

#[derive(Debug, Serialize)]
struct Envelope<T> {
    ok: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    data: Option<T>,
    #[serde(skip_serializing_if = "Option::is_none")]
    error: Option<ApiError>,
}

/// A failure that maps to one JSON error and one exit code.
#[derive(Debug)]
pub struct Failure {
    pub code: ErrorCode,
    pub message: String,
}

impl Failure {
    #[must_use]
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    #[must_use]
    pub fn internal(message: impl Into<String>) -> Self {
        Self::new(ErrorCode::Internal, message)
    }

    #[must_use]
    pub fn usage(message: impl Into<String>) -> Self {
        Self::new(ErrorCode::BadRequest, message)
    }

    #[must_use]
    pub const fn exit_code(&self) -> u8 {
        match self.code {
            ErrorCode::BadRequest => 2,
            ErrorCode::Unauthorized => 3,
            ErrorCode::NotFound => 4,
            ErrorCode::Backend => 5,
            ErrorCode::Playback => 6,
            ErrorCode::Daemon => 7,
            ErrorCode::Unsupported => 8,
            ErrorCode::Internal => 1,
        }
    }

    #[must_use]
    pub fn api_error(&self) -> ApiError {
        ApiError::new(self.code, self.message.clone())
    }
}

impl From<IpcError> for Failure {
    fn from(error: IpcError) -> Self {
        match error {
            IpcError::NotRunning { path } => Self::new(
                ErrorCode::Daemon,
                format!(
                    "the player daemon is not running at {}; start it with `lekima daemon start`",
                    path.display()
                ),
            ),
            IpcError::Remote { code, message } => Self::new(code, message),
            other => Self::new(ErrorCode::Daemon, other.to_string()),
        }
    }
}

impl From<lekima_domain::DomainError> for Failure {
    fn from(error: lekima_domain::DomainError) -> Self {
        let api: ApiError = error.into();
        Self::new(api.code, api.message)
    }
}

impl From<lekima_config::paths::PathError> for Failure {
    fn from(error: lekima_config::paths::PathError) -> Self {
        Self::new(ErrorCode::Internal, error.to_string())
    }
}

/// Prints a successful reply and exits 0.
pub fn print_reply(reply: &Reply, json: bool) {
    if json {
        emit_json(true, Some(reply_data(reply)), None);
        return;
    }
    match reply {
        Reply::Status { state } => print_status(state),
        Reply::Tracks { tracks } => print_tracks(tracks),
        Reply::Search { results } => print_search(results),
        Reply::Playlists { playlists } => print_playlists(playlists),
        Reply::Queue { tracks, index } => print_queue(tracks, *index),
        Reply::User { user } => match user {
            Some(user) => println!("{} ({})", user.nickname, user.id),
            None => println!("not signed in"),
        },
        Reply::Lyrics { text } => println!("{text}"),
        Reply::Ack | Reply::Pong => {}
    }
}

/// Serializes a reply for agents. `status` is flattened so `data.status` is the
/// playback status, matching the documented contract.
#[must_use]
pub fn reply_data(reply: &Reply) -> Value {
    match reply {
        Reply::Status { state } => serde_json::to_value(state).unwrap_or(Value::Null),
        other => serde_json::to_value(other).unwrap_or(Value::Null),
    }
}

pub fn emit_json(data_ok: bool, data: Option<Value>, error: Option<ApiError>) {
    let envelope: Envelope<Value> = Envelope {
        ok: data_ok,
        data,
        error,
    };
    match serde_json::to_string(&envelope) {
        Ok(encoded) => println!("{encoded}"),
        Err(_) => println!(r#"{{"ok":false,"error":{{"code":"internal","message":"serialization failed"}}}}"#),
    }
}

pub fn print_failure(failure: &Failure, json: bool) {
    if json {
        emit_json(false, None, Some(failure.api_error()));
    } else {
        eprintln!("error: {}", failure.message);
    }
}

fn print_status(state: &PlaybackState) {
    let track = state
        .track
        .as_ref()
        .map_or_else(|| "nothing playing".to_owned(), |track| {
            format!("{} — {}", track.name, track.artist_names())
        });
    println!(
        "{}  {}  [{}/{}]  vol {:.0}%  repeat {}  queue {}",
        icon(state),
        track,
        format_ms(state.position_ms),
        state
            .track
            .as_ref()
            .map_or("--:--".to_owned(), |track| format_ms(track.duration_ms)),
        state.effective_volume() * 100.0,
        state.repeat.as_str(),
        state.queue_length,
    );
}

fn icon(state: &PlaybackState) -> &'static str {
    match state.status {
        lekima_domain::PlaybackStatus::Playing => "▶",
        lekima_domain::PlaybackStatus::Paused => "⏸",
        lekima_domain::PlaybackStatus::Stopped => "■",
    }
}

fn print_tracks(tracks: &[Track]) {
    for (index, track) in tracks.iter().enumerate() {
        println!(
            "{:>4}  {:<40} {:<22} {:>6}  {}",
            index + 1,
            truncate(&track.name, 40),
            truncate(&track.artist_names(), 22),
            track.duration_label(),
            track.id
        );
    }
    if tracks.is_empty() {
        println!("no tracks");
    }
}

fn print_search(results: &SearchResults) {
    print_tracks(&results.tracks);
}

fn print_playlists(playlists: &[Playlist]) {
    for playlist in playlists {
        println!(
            "{:>10}  {:<40} {}",
            playlist.id,
            truncate(&playlist.name, 40),
            playlist.track_count
        );
    }
    if playlists.is_empty() {
        println!("no playlists");
    }
}

fn print_queue(tracks: &[Track], index: Option<usize>) {
    for (position, track) in tracks.iter().enumerate() {
        let marker = if Some(position) == index { "▶" } else { " " };
        println!(
            "{marker} {:>3}  {} — {}",
            position + 1,
            track.name,
            track.artist_names()
        );
    }
}

fn format_ms(ms: u64) -> String {
    let seconds = ms / 1000;
    format!("{}/{:02}", seconds / 60, seconds % 60)
}

fn truncate(value: &str, width: usize) -> String {
    if value.chars().count() <= width {
        return value.to_owned();
    }
    let mut truncated: String = value.chars().take(width.saturating_sub(1)).collect();
    truncated.push('…');
    truncated
}

//! The player daemon: owns the audio engine, the provider session and the
//! queue. Every other process is a client.

use std::{
    fs,
    io::Write,
    os::unix::fs::{OpenOptionsExt, PermissionsExt},
    path::Path,
    sync::Arc,
    time::{Duration, Instant},
};

use anyhow::{Context, Result};
use lekima_config::{Config, FileCredentials, Paths};
use lekima_core::{PlayRequest, Player};
use lekima_domain::{
    CredentialsStore, MusicService, PlaybackState, PlaybackStatus, RepeatMode, SearchKind,
    TrackId, UserId,
};
use lekima_ipc::{ApiError, Command, PlayTarget, Reply, Request, Response, serve_connection};
use lekima_ncm::{NcmMusicService, NcmOptions};
use tokio::{net::UnixListener, sync::Notify};

use crate::output::Failure;

/// Runs the daemon until it is asked to shut down.
///
/// # Errors
///
/// Fails when the socket cannot be bound, or when the audio device or provider
/// client cannot be initialised.
pub async fn run(paths: &Paths, config: &Config, _detached: bool) -> Result<()> {
    paths.ensure().context("failed to create state directories")?;
    let socket = paths.socket();
    prepare_socket(&socket)?;

    let listener = UnixListener::bind(&socket)
        .with_context(|| format!("failed to bind {}", socket.display()))?;
    fs::set_permissions(&socket, fs::Permissions::from_mode(0o600))
        .context("failed to restrict socket permissions")?;
    tracing::info!(socket = %socket.display(), "daemon listening");

    let music = Arc::new(NcmMusicService::new(NcmOptions {
        cookie_path: paths.session_file(),
        cache: config.provider.cache,
        cache_ttl: Duration::from_secs(config.provider.cache_ttl_secs),
    })?);
    let audio = Arc::new(
        lekima_audio::RodioAudioEngine::open(config.playback.volume)
            .map_err(|error| anyhow::anyhow!(error.to_string()))?,
    );
    let player = Arc::new(Player::new(
        music,
        audio,
        config.playback.quality,
        config.playback.volume,
    ));

    let daemon = Arc::new(Daemon {
        player: Arc::clone(&player),
        credentials: FileCredentials::new(paths.session_file()),
        started: Instant::now(),
        shutdown: Notify::new(),
    });

    spawn_ticker(Arc::clone(&player));

    let mut terminate =
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .context("failed to install the SIGTERM handler")?;

    loop {
        tokio::select! {
            accepted = listener.accept() => {
                match accepted {
                    Ok((stream, _)) => {
                        let daemon = Arc::clone(&daemon);
                        tokio::spawn(async move {
                            let handler = {
                                let daemon = Arc::clone(&daemon);
                                move |request: Request| {
                                    let daemon = Arc::clone(&daemon);
                                    async move { daemon.handle(request).await }
                                }
                            };
                            if let Err(error) = serve_connection(stream, handler).await {
                                tracing::warn!(%error, "ipc connection failed");
                            }
                        });
                    }
                    Err(error) => tracing::warn!(%error, "accept failed"),
                }
            }
            () = daemon.shutdown.notified() => break,
            _ = tokio::signal::ctrl_c() => break,
            _ = terminate.recv() => break,
        }
    }

    tracing::info!("shutting down");
    let _ = daemon.player.stop().await;
    drop(listener);
    let _ = fs::remove_file(&socket);
    Ok(())
}

struct Daemon {
    player: Arc<Player>,
    credentials: FileCredentials,
    started: Instant,
    shutdown: Notify,
}

impl Daemon {
    async fn handle(&self, request: Request) -> Response {
        let id = request.id;
        match self.execute(request.command).await {
            Ok(reply) => Response::ok(id, reply),
            Err(error) => Response::err(id, error),
        }
    }

    async fn execute(&self, command: Command) -> std::result::Result<Reply, ApiError> {
        match command {
            Command::Ping => Ok(Reply::Pong),
            Command::Status => Ok(self.status().await),
            Command::Play { target } => {
                self.play(target).await?;
                Ok(self.status().await)
            }
            Command::Jump { index } => {
                self.player.play(PlayRequest::Index(index)).await?;
                Ok(self.status().await)
            }
            Command::Pause => {
                self.player.pause().await?;
                Ok(self.status().await)
            }
            Command::Resume => {
                self.player.resume().await?;
                Ok(self.status().await)
            }
            Command::Toggle => {
                self.player.toggle().await?;
                Ok(self.status().await)
            }
            Command::Stop => {
                self.player.stop().await?;
                Ok(self.status().await)
            }
            Command::Next => {
                self.player.next().await?;
                Ok(self.status().await)
            }
            Command::Prev => {
                self.player.previous().await?;
                Ok(self.status().await)
            }
            Command::Seek { position_ms } => {
                self.player.seek(position_ms).await?;
                Ok(self.status().await)
            }
            Command::SetVolume { level } => {
                self.player.set_volume(level).await?;
                Ok(self.status().await)
            }
            Command::ToggleMute => {
                self.player.toggle_mute().await?;
                Ok(self.status().await)
            }
            Command::CycleRepeat => {
                self.player.cycle_repeat().await;
                Ok(self.status().await)
            }
            Command::SetRepeat { mode } => {
                self.player.set_repeat(mode).await;
                Ok(self.status().await)
            }
            Command::SetShuffle { enabled } => {
                self.player.set_shuffle(enabled).await?;
                Ok(self.status().await)
            }
            Command::Queue => {
                let (tracks, index) = self.player.queue().await;
                Ok(Reply::Queue { tracks, index })
            }
            Command::Enqueue { tracks, next } => {
                let resolved = self.player.resolve_tracks(&tracks).await?;
                self.player.enqueue(resolved, next).await?;
                Ok(Reply::Ack)
            }
            Command::ClearQueue => {
                self.player.clear_queue().await?;
                Ok(Reply::Ack)
            }
            Command::Search {
                query,
                kind,
                limit,
                offset,
            } => {
                let results = self
                    .player
                    .music()
                    .search(&query, kind, limit, offset)
                    .await?;
                Ok(Reply::Search { results })
            }
            Command::Playlists => {
                let playlists = self.player.music().playlists(None).await?;
                Ok(Reply::Playlists { playlists })
            }
            Command::PlaylistTracks { id } => {
                let tracks = self.player.music().playlist_tracks(id).await?;
                Ok(Reply::Tracks { tracks })
            }
            Command::Lyrics { id } => {
                let track_id = match id {
                    Some(id) => id,
                    None => self
                        .player
                        .snapshot()
                        .await
                        .track
                        .map_or_else(
                            || {
                                Err(ApiError::new(
                                    lekima_ipc::ErrorCode::NotFound,
                                    "nothing is playing",
                                ))
                            },
                            |track| Ok(track.id),
                        )?,
                };
                let text = self.player.music().lyrics(track_id).await?;
                Ok(Reply::Lyrics { text })
            }
            Command::Whoami => {
                let user = self.player.music().current_user().await?;
                Ok(Reply::User { user })
            }
            Command::Login { cookie } => {
                self.credentials.save(&cookie)?;
                Ok(Reply::Ack)
            }
            Command::Logout => {
                self.credentials.clear()?;
                Ok(Reply::Ack)
            }
            Command::Shutdown => {
                self.shutdown.notify_waiters();
                Ok(Reply::Ack)
            }
        }
    }

    async fn play(&self, target: PlayTarget) -> std::result::Result<(), ApiError> {
        let tracks = match target {
            PlayTarget::Query { query } => {
                let results = self
                    .player
                    .music()
                    .search(&query, SearchKind::Track, 25, 0)
                    .await?;
                if results.tracks.is_empty() {
                    return Err(ApiError::new(
                        lekima_ipc::ErrorCode::NotFound,
                        format!("no tracks matched `{query}`"),
                    ));
                }
                results.tracks
            }
            PlayTarget::Tracks { ids } => self.player.resolve_tracks(&ids).await?,
            PlayTarget::Playlist { id } => self.player.music().playlist_tracks(id).await?,
        };
        self.player.play(PlayRequest::Tracks(tracks)).await?;
        Ok(())
    }

    async fn status(&self) -> Reply {
        let state: PlaybackState = self.player.snapshot().await;
        let _ = (self.started, PlaybackStatus::Stopped, RepeatMode::Off, TrackId(0), UserId(0));
        Reply::Status { state }
    }
}

fn spawn_ticker(player: Arc<Player>) {
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(Duration::from_millis(500));
        loop {
            interval.tick().await;
            if let Err(error) = player.tick().await {
                tracing::warn!(%error, "auto-advance failed");
            }
        }
    });
}

fn prepare_socket(socket: &Path) -> Result<()> {
    if let Some(parent) = socket.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("failed to create {}", parent.display()))?;
        fs::set_permissions(parent, fs::Permissions::from_mode(0o700))
            .with_context(|| format!("failed to restrict {}", parent.display()))?;
    }
    if socket.exists() {
        if std::os::unix::net::UnixStream::connect(socket).is_ok() {
            anyhow::bail!(
                "another lekima daemon is already listening on {}",
                socket.display()
            );
        }
        fs::remove_file(socket)
            .with_context(|| format!("failed to remove stale socket {}", socket.display()))?;
    }
    Ok(())
}

/// Starts a detached daemon that logs to `log_file`.
///
/// # Errors
///
/// Propagates process-spawn and log-file failures.
pub fn spawn_detached(socket: &Path, log_file: &Path) -> Result<()> {
    let executable = std::env::current_exe().context("failed to locate the current binary")?;
    if let Some(parent) = log_file.parent() {
        fs::create_dir_all(parent)?;
    }
    let log = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .mode(0o600)
        .open(log_file)
        .with_context(|| format!("failed to open {}", log_file.display()))?;
    let errors = log.try_clone().context("failed to clone the log file")?;
    let mut command = std::process::Command::new(executable);
    command
        .arg("--socket")
        .arg(socket)
        .args(["daemon", "run", "--detached"])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::from(log))
        .stderr(std::process::Stdio::from(errors))
        .env("LEKIMA_LOG", "info");
    command.spawn().context("failed to spawn the daemon")?;
    Ok(())
}

/// Waits until the daemon answers a ping.
///
/// # Errors
///
/// Returns [`Failure`] with code `daemon` when the deadline passes.
pub async fn wait_until_running(socket: &Path, deadline: Duration) -> std::result::Result<(), Failure> {
    let started = Instant::now();
    while started.elapsed() < deadline {
        if lekima_ipc::is_running(socket).await {
            return Ok(());
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    Err(Failure::new(
        lekima_ipc::ErrorCode::Daemon,
        format!(
            "the daemon did not start within {}s; see {}",
            deadline.as_secs(),
            "the log file (`lekima daemon logs`)"
        ),
    ))
}

/// Appends a line to the daemon log (used by clients for hints).
pub fn append_log(log_file: &Path, line: &str) {
    if let Ok(mut file) = fs::OpenOptions::new().create(true).append(true).open(log_file) {
        let _ = writeln!(file, "{line}");
    }
}

//! Command dispatch: the composition root that wires adapters to the CLI.

use std::{
    io::Read,
    path::{Path, PathBuf},
    time::Duration,
};

use clap::CommandFactory;
use lekima_config::{Config, FileCredentials, Paths};
use lekima_domain::{CredentialsStore, MusicService, PlaybackState};
use lekima_ipc::{Command, ErrorCode, PlayTarget, Reply, call, is_running};
use lekima_ncm::{NcmMusicService, NcmOptions};

use crate::{
    cli::{Cli, DaemonCommand, PlaylistCommand, QueueCommand, TopCommand},
    daemon,
    output::{self, Failure},
};

pub async fn execute(cli: Cli, paths: Paths, config: Config) -> Result<(), Failure> {
    let socket = cli.socket.clone().unwrap_or_else(|| paths.socket());
    let json = cli.json;

    match cli.command {
        TopCommand::Tui => {
            ensure_daemon(&socket, &paths, &config).await?;
            lekima_tui::run(socket)
                .await
                .map_err(|error| Failure::internal(error.to_string()))?;
            Ok(())
        }

        TopCommand::Play {
            query,
            ids,
            playlist,
        } => {
            let target = if !ids.is_empty() {
                PlayTarget::Tracks {
                    ids: ids.into_iter().map(Into::into).collect(),
                }
            } else if let Some(id) = playlist {
                PlayTarget::Playlist { id: id.into() }
            } else {
                let query = query.join(" ");
                if query.trim().is_empty() {
                    return Err(Failure::usage(
                        "nothing to play: pass a query, --id or --playlist",
                    ));
                }
                PlayTarget::Query { query }
            };
            let reply = daemon_call(&socket, &paths, &config, Command::Play { target }).await?;
            output::print_reply(&reply, json);
            Ok(())
        }

        TopCommand::Pause => simple(&socket, &paths, &config, Command::Pause, json).await,
        TopCommand::Resume => simple(&socket, &paths, &config, Command::Resume, json).await,
        TopCommand::Toggle => simple(&socket, &paths, &config, Command::Toggle, json).await,
        TopCommand::Stop => simple(&socket, &paths, &config, Command::Stop, json).await,
        TopCommand::Next => simple(&socket, &paths, &config, Command::Next, json).await,
        TopCommand::Prev => simple(&socket, &paths, &config, Command::Prev, json).await,

        TopCommand::Seek { position } => {
            let offset = parse_position(&position)?;
            let target = if offset < 0 || position.trim_start().starts_with('+') {
                let reply = daemon_call(&socket, &paths, &config, Command::Status).await?;
                let state = state_of(&reply)?;
                let base = i64::try_from(state.position_ms).unwrap_or(i64::MAX);
                u64::try_from((base + offset).max(0)).unwrap_or(0)
            } else {
                u64::try_from(offset).unwrap_or(0)
            };
            let reply = daemon_call(
                &socket,
                &paths,
                &config,
                Command::Seek {
                    position_ms: target,
                },
            )
            .await?;
            output::print_reply(&reply, json);
            Ok(())
        }

        TopCommand::Volume {
            level,
            mute,
            unmute,
        } => {
            let command = if mute || unmute {
                let reply = daemon_call(&socket, &paths, &config, Command::Status).await?;
                let state = state_of(&reply)?;
                if state.muted == mute {
                    Command::ToggleMute
                } else {
                    Command::Status
                }
            } else {
                let level = level.ok_or_else(|| {
                    Failure::usage("pass a level (0-100), --mute or --unmute")
                })?;
                Command::SetVolume {
                    level: parse_volume(&level)?,
                }
            };
            let reply = daemon_call(&socket, &paths, &config, command).await?;
            output::print_reply(&reply, json);
            Ok(())
        }

        TopCommand::Queue { action } => match action.unwrap_or(QueueCommand::List) {
            QueueCommand::List => {
                let reply = daemon_call(&socket, &paths, &config, Command::Queue).await?;
                output::print_reply(&reply, json);
                Ok(())
            }
            QueueCommand::Add { query, ids, next } => {
                let ids = if ids.is_empty() {
                    let query = query.join(" ");
                    if query.trim().is_empty() {
                        return Err(Failure::usage("pass a query or --id"));
                    }
                    let service = service(&paths, &config)?;
                    let results = service
                        .search(&query, lekima_domain::SearchKind::Track, 25, 0)
                        .await?;
                    if results.tracks.is_empty() {
                        return Err(Failure::new(
                            ErrorCode::NotFound,
                            format!("no tracks matched `{query}`"),
                        ));
                    }
                    results.tracks.into_iter().map(|track| track.id).collect()
                } else {
                    ids.into_iter().map(Into::into).collect()
                };
                let reply = daemon_call(
                    &socket,
                    &paths,
                    &config,
                    Command::Enqueue {
                        tracks: ids,
                        next,
                    },
                )
                .await?;
                output::print_reply(&reply, json);
                Ok(())
            }
            QueueCommand::Clear => {
                simple(&socket, &paths, &config, Command::ClearQueue, json).await
            }
        },

        TopCommand::Search {
            query,
            kind,
            limit,
            offset,
        } => {
            let query = query.join(" ");
            let service = service(&paths, &config)?;
            let results = service.search(&query, kind.into(), limit, offset).await?;
            output::print_reply(&Reply::Search { results }, json);
            Ok(())
        }

        TopCommand::Playlist { action } => {
            let service = service(&paths, &config)?;
            match action {
                PlaylistCommand::List => {
                    let playlists = service.playlists(None).await?;
                    output::print_reply(&Reply::Playlists { playlists }, json);
                }
                PlaylistCommand::Show { id } => {
                    let tracks = service.playlist_tracks(id.into()).await?;
                    output::print_reply(&Reply::Tracks { tracks }, json);
                }
            }
            Ok(())
        }

        TopCommand::Lyrics { id } => {
            let reply = daemon_call(
                &socket,
                &paths,
                &config,
                Command::Lyrics {
                    id: id.map(Into::into),
                },
            )
            .await?;
            output::print_reply(&reply, json);
            Ok(())
        }

        TopCommand::Status => {
            let reply = daemon_call(&socket, &paths, &config, Command::Status).await?;
            output::print_reply(&reply, json);
            Ok(())
        }

        TopCommand::Login { cookie_file, qr } => login(&paths, &socket, cookie_file, qr, json).await,

        TopCommand::Logout => logout(&paths, &socket, json).await,

        TopCommand::Whoami => {
            let service = service(&paths, &config)?;
            let user = service.current_user().await?;
            output::print_reply(&Reply::User { user }, json);
            Ok(())
        }

        TopCommand::Daemon { action } => daemon_command(action, &socket, &paths, &config, json).await,

        TopCommand::Doctor => doctor(&socket, &paths, &config, json).await,

        TopCommand::Capabilities => {
            let tree = command_tree(&Cli::command());
            if json {
                output::emit_json(true, Some(tree), None);
            } else {
                let encoded = serde_json::to_string_pretty(&tree)
                    .map_err(|error| Failure::internal(error.to_string()))?;
                println!("{encoded}");
            }
            Ok(())
        }

        TopCommand::Completions { shell } => {
            let mut command = Cli::command();
            clap_complete::generate(shell, &mut command, "lekima", &mut std::io::stdout());
            Ok(())
        }
    }
}

async fn simple(
    socket: &Path,
    paths: &Paths,
    config: &Config,
    command: Command,
    json: bool,
) -> Result<(), Failure> {
    let reply = daemon_call(socket, paths, config, command).await?;
    output::print_reply(&reply, json);
    Ok(())
}

fn service(paths: &Paths, config: &Config) -> Result<NcmMusicService, Failure> {
    NcmMusicService::new(NcmOptions {
        cookie_path: paths.session_file(),
        cache: config.provider.cache,
        cache_ttl: Duration::from_secs(config.provider.cache_ttl_secs),
    })
    .map_err(Into::into)
}

async fn daemon_call(
    socket: &Path,
    paths: &Paths,
    config: &Config,
    command: Command,
) -> Result<Reply, Failure> {
    match call(socket, command.clone()).await {
        Ok(reply) => Ok(reply),
        Err(error) if error.is_not_running() && config.daemon.autostart => {
            daemon::spawn_detached(socket, &paths.log_file())
                .map_err(|error| Failure::new(ErrorCode::Daemon, error.to_string()))?;
            daemon::wait_until_running(socket, Duration::from_secs(10)).await?;
            call(socket, command).await.map_err(Into::into)
        }
        Err(error) => Err(error.into()),
    }
}

async fn ensure_daemon(socket: &Path, paths: &Paths, config: &Config) -> Result<(), Failure> {
    if is_running(socket).await {
        return Ok(());
    }
    if !config.daemon.autostart {
        return Err(Failure::new(
            ErrorCode::Daemon,
            format!(
                "no daemon at {} and autostart is disabled",
                socket.display()
            ),
        ));
    }
    daemon::spawn_detached(socket, &paths.log_file())
        .map_err(|error| Failure::new(ErrorCode::Daemon, error.to_string()))?;
    daemon::wait_until_running(socket, Duration::from_secs(10)).await
}

fn state_of(reply: &Reply) -> Result<PlaybackState, Failure> {
    match reply {
        Reply::Status { state } => Ok(state.clone()),
        _ => Err(Failure::internal("daemon returned an unexpected reply")),
    }
}

async fn login(
    paths: &Paths,
    socket: &Path,
    cookie_file: Option<PathBuf>,
    qr: bool,
    json: bool,
) -> Result<(), Failure> {
    if qr {
        return Err(Failure::new(
            ErrorCode::Unsupported,
            "QR login requires ncmapi 1.1; for now use `lekima login --cookie-file -` with a browser cookie",
        ));
    }

    let cookie = match cookie_file {
        Some(path) if path == Path::new("-") => read_stdin()?,
        Some(path) => std::fs::read_to_string(&path)
            .map_err(|error| Failure::usage(format!("failed to read {}: {error}", path.display())))?,
        None => read_stdin()?,
    };
    let cookie = cookie.trim().to_owned();
    if !cookie.contains('=') || !cookie.to_ascii_uppercase().contains("MUSIC_U") {
        return Err(Failure::usage(
            "that does not look like a music.163.com cookie header (expected `MUSIC_U=<redacted>",
        ));
    }

    FileCredentials::new(paths.session_file()).save(&cookie)?;
    restart_daemon(socket).await;

    if json {
        output::emit_json(
            true,
            Some(serde_json::json!({ "saved": true, "session_file": paths.session_file() })),
            None,
        );
    } else {
        println!(
            "session saved to {}; the next command starts a fresh daemon",
            paths.session_file().display()
        );
    }
    Ok(())
}

async fn logout(paths: &Paths, socket: &Path, json: bool) -> Result<(), Failure> {
    FileCredentials::new(paths.session_file()).clear()?;
    restart_daemon(socket).await;
    if json {
        output::emit_json(true, Some(serde_json::json!({ "saved": false })), None);
    } else {
        println!("session removed");
    }
    Ok(())
}

async fn restart_daemon(socket: &Path) {
    if is_running(socket).await {
        let _ = call(socket, Command::Shutdown).await;
        for _ in 0..30 {
            if !is_running(socket).await {
                break;
            }
            tokio::time::sleep(Duration::from_millis(100)).await;
        }
    }
}

async fn daemon_command(
    action: DaemonCommand,
    socket: &Path,
    paths: &Paths,
    config: &Config,
    json: bool,
) -> Result<(), Failure> {
    match action {
        DaemonCommand::Start => {
            if is_running(socket).await {
                return report_running(socket, false, json);
            }
            daemon::spawn_detached(socket, &paths.log_file())
                .map_err(|error| Failure::new(ErrorCode::Daemon, error.to_string()))?;
            daemon::wait_until_running(socket, Duration::from_secs(10)).await?;
            report_running(socket, true, json)
        }
        DaemonCommand::Stop => {
            if !is_running(socket).await {
                if json {
                    output::emit_json(true, Some(serde_json::json!({ "running": false })), None);
                } else {
                    println!("daemon is not running");
                }
                return Ok(());
            }
            let _ = call(socket, Command::Shutdown).await;
            for _ in 0..30 {
                if !is_running(socket).await {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(100)).await;
            }
            if json {
                output::emit_json(true, Some(serde_json::json!({ "running": false })), None);
            } else {
                println!("daemon stopped");
            }
            Ok(())
        }
        DaemonCommand::Status => report_running(socket, false, json),
        DaemonCommand::Run { detached } => daemon::run(paths, config, detached)
            .await
            .map_err(|error| Failure::internal(error.to_string())),
        DaemonCommand::Logs { lines } => {
            let raw = std::fs::read_to_string(paths.log_file()).unwrap_or_default();
            let tail: Vec<_> = raw.lines().rev().take(lines).collect::<Vec<_>>().into_iter().rev().collect();
            println!("{}", tail.join("\n"));
            Ok(())
        }
    }
}

fn report_running(socket: &Path, started: bool, json: bool) -> Result<(), Failure> {
    let running = std::os::unix::net::UnixStream::connect(socket).is_ok();
    if json {
        output::emit_json(
            true,
            Some(serde_json::json!({
                "running": running,
                "started": started,
                "socket": socket,
            })),
            None,
        );
    } else if running {
        println!("daemon running at {}", socket.display());
    } else {
        println!("daemon is not running");
    }
    Ok(())
}

async fn doctor(
    socket: &Path,
    paths: &Paths,
    config: &Config,
    json: bool,
) -> Result<(), Failure> {
    let session_present = FileCredentials::new(paths.session_file())
        .load()?
        .is_some();
    let daemon_running = is_running(socket).await;

    let audio = match lekima_audio::RodioAudioEngine::open(0.0) {
        Ok(engine) => {
            drop(engine);
            serde_json::json!({ "ok": true })
        }
        Err(error) => serde_json::json!({ "ok": false, "error": error.to_string() }),
    };

    let provider = match service(paths, config) {
        Ok(service) => match tokio::time::timeout(Duration::from_secs(8), service.current_user()).await
        {
            Ok(Ok(user)) => serde_json::json!({
                "ok": true,
                "signed_in": user.is_some(),
            }),
            Ok(Err(error)) => serde_json::json!({ "ok": false, "error": error.to_string() }),
            Err(_) => serde_json::json!({ "ok": false, "error": "timed out" }),
        },
        Err(error) => serde_json::json!({ "ok": false, "error": error.message }),
    };

    let report = serde_json::json!({
        "version": env!("CARGO_PKG_VERSION"),
        "socket": { "path": socket, "daemon_running": daemon_running },
        "session": { "present": session_present, "file": paths.session_file() },
        "config": { "file": paths.config_file(), "loaded": true },
        "audio": audio,
        "provider": provider,
        "log": paths.log_file(),
    });

    if json {
        output::emit_json(true, Some(report), None);
        return Ok(());
    }

    println!("lekima {} ({})", env!("CARGO_PKG_VERSION"), std::env::consts::OS);
    println!(
        "daemon   {} at {}",
        if daemon_running { "running" } else { "not running" },
        socket.display()
    );
    println!(
        "session  {} ({})",
        if session_present { "present" } else { "missing" },
        paths.session_file().display()
    );
    println!("config   {}", paths.config_file().display());
    println!("audio    {audio}");
    println!("provider {provider}");
    println!("log      {}", paths.log_file().display());
    Ok(())
}

fn command_tree(command: &clap::Command) -> serde_json::Value {
    let subcommands: Vec<_> = command
        .get_subcommands()
        .map(command_tree)
        .filter(|value| value["name"] != "help")
        .collect();
    serde_json::json!({
        "name": command.get_name(),
        "about": command.get_about().map(ToString::to_string),
        "options": command
            .get_arguments()
            .filter(|argument| argument.get_id() != "help" && argument.get_id() != "version")
            .map(|argument| serde_json::json!({
                "name": argument.get_id().to_string(),
                "short": argument.get_short(),
                "long": argument.get_long(),
                "help": argument.get_help().map(ToString::to_string),
                "takes_value": argument.get_action().takes_values(),
            }))
            .collect::<Vec<_>>(),
        "subcommands": subcommands,
    })
}

fn parse_volume(raw: &str) -> Result<f32, Failure> {
    let trimmed = raw.trim().trim_end_matches('%');
    let value: f32 = trimmed
        .parse()
        .map_err(|_| Failure::usage(format!("`{raw}` is not a volume level")))?;
    let fraction = if value > 1.0 { value / 100.0 } else { value };
    if !(0.0..=1.0).contains(&fraction) {
        return Err(Failure::usage("volume must be between 0 and 100"));
    }
    Ok(fraction)
}

/// Parses `1:23`, `83`, `83s`, `2m`, `+10s`, `-10s` into milliseconds.
fn parse_position(raw: &str) -> Result<i64, Failure> {
    let raw = raw.trim();
    let (sign, body) = match raw.strip_prefix('-') {
        Some(rest) => (-1, rest),
        None => (1, raw.strip_prefix('+').unwrap_or(raw)),
    };
    if body.is_empty() {
        return Err(Failure::usage("empty position"));
    }

    let millis = if body.contains(':') {
        let mut total = 0i64;
        for part in body.split(':') {
            let value: i64 = part
                .parse()
                .map_err(|_| Failure::usage(format!("`{raw}` is not a position")))?;
            total = total * 60 + value;
        }
        total * 1000
    } else if let Some(hours) = body.strip_suffix('h') {
        hours.parse::<i64>().map_err(|_| Failure::usage("invalid hours"))? * 3_600_000
    } else if let Some(minutes) = body.strip_suffix('m') {
        minutes.parse::<i64>().map_err(|_| Failure::usage("invalid minutes"))? * 60_000
    } else {
        let seconds = body.strip_suffix('s').unwrap_or(body);
        seconds
            .parse::<f64>()
            .map_err(|_| Failure::usage(format!("`{raw}` is not a position")))?
            .mul_add(1000.0, 0.0) as i64
    };

    Ok(sign * millis)
}

fn read_stdin() -> Result<String, Failure> {
    let mut buffer = String::new();
    std::io::stdin()
        .read_to_string(&mut buffer)
        .map_err(|error| Failure::usage(format!("failed to read stdin: {error}")))?;
    if buffer.trim().is_empty() {
        return Err(Failure::usage(
            "stdin was empty; pipe the cookie header, e.g. `lekima login --cookie-file -`",
        ));
    }
    Ok(buffer)
}

#[cfg(test)]
mod tests {
    use super::{parse_position, parse_volume};

    #[test]
    fn positions_support_colons_and_units() {
        assert_eq!(parse_position("1:23").unwrap(), 83_000);
        assert_eq!(parse_position("83s").unwrap(), 83_000);
        assert_eq!(parse_position("2m").unwrap(), 120_000);
        assert_eq!(parse_position("+10s").unwrap(), 10_000);
        assert_eq!(parse_position("-10s").unwrap(), -10_000);
    }

    #[test]
    fn volume_accepts_percent_and_fraction() {
        assert!((parse_volume("70").unwrap() - 0.7).abs() < f32::EPSILON);
        assert!((parse_volume("70%").unwrap() - 0.7).abs() < f32::EPSILON);
        assert!((parse_volume("0.7").unwrap() - 0.7).abs() < f32::EPSILON);
        assert!(parse_volume("140").is_err());
    }
}

